-- ============================================================
-- 0075_rondas_banco_preguntas.sql
-- GENERADO por scripts/build-rondas.mjs — no editar a mano: cambia el banco
-- (src/lib/questionBank.json) y vuelve a correr el script.
--
-- Módulos 4 (primera ronda) y 6 (ronda final) de las rutas de 7 módulos:
-- pasan a ser rondas de preguntas que la Clase en Vivo sincroniza una a una
-- (tipo Kahoot). Por dentro son un reto 'quiz' — es lo único que el modo en
-- vivo sabe recorrer pregunta a pregunta —, pero conservan su id, título,
-- orden, XP y progreso, y el mapa los sigue rotulando como MÓDULO
-- (challenge_data.bank, ver src/lib/questionBankMeta.js).
--
-- Preguntas predeterminadas (el tutor las cambia desde el editor de ruta,
-- eligiendo del banco):
--   Matemáticas  primera ronda 10 · ronda final 10 · banco 20
--   Lenguaje     primera ronda 10 · ronda final 10 · banco 75
--   Biología     primera ronda 10 · ronda final 10 · banco 25
--   Física       primera ronda 10 · ronda final 10 · banco 25
--   Química      primera ronda 10 · ronda final 10 · banco 25
--   Ciencias Sociales: aún no hay preguntas → sus módulos 4 y 6 no se tocan.
--
-- Qué hace:
--   1. _snapshot_module_questions: la clase en vivo ahora también lleva a los
--      estudiantes el texto de lectura (passage), la pista del tutor (hint) y
--      la segunda parte del enunciado (questionAfter). La respuesta correcta
--      sigue SOLO en live_session_keys, igual que antes.
--   2. En cada curso de esas asignaturas (curso base + copias por colegio)
--      convierte los módulos de "order" 4 y 6 SOLO si siguen sin contenido
--      propio: dicen "Pendiente" o traen el banco viejo en texto (0064).
--      Si un tutor ya los editó a mano, NO se tocan (lo informa).
--
-- Idempotente: lo ya convertido se informa como "YA APLICADA".
-- EJECUTAR en Supabase SQL Editor.
-- ============================================================

-- ── 1. Snapshot de preguntas con texto de lectura y pista ───────────────
create or replace function public._snapshot_module_questions(p_module_id uuid, p_default_time int default 20)
returns jsonb
language plpgsql set search_path = public as $$
declare
  v_questions jsonb;
  v_snapshot  jsonb := '[]'::jsonb;
  v_keys      jsonb := '[]'::jsonb;
  q jsonb;
begin
  select challenge_data->'questions' into v_questions from public.course_modules where id = p_module_id;

  for q in select value from jsonb_array_elements(coalesce(v_questions, '[]'::jsonb)) as t(value) loop
    v_snapshot := v_snapshot || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'question',      q->>'question',
      'questionAfter', q->>'questionAfter',
      'options',       coalesce(q->'options', '[]'::jsonb),
      'image',         q->>'image',
      'imageHeight',   q->'imageHeight',
      'passage',       q->'passage',
      'hint',          q->>'hint',
      'time_limit_s',  coalesce(nullif(q->>'timeLimit','')::int, p_default_time)
    )));
    v_keys := v_keys || jsonb_build_array(jsonb_build_object(
      'correct',          (q->>'correct')::int,
      'points',           coalesce(nullif(q->>'points','')::int, 1000),
      'time_limit_s',     coalesce(nullif(q->>'timeLimit','')::int, p_default_time),
      'explanation',      q->>'explanation',
      'explanationImage', q->>'explanationImage'
    ));
  end loop;

  return jsonb_build_object('snapshot', v_snapshot, 'keys', v_keys);
end; $$;
revoke execute on function public._snapshot_module_questions(uuid, int) from public;

-- ── 2. Rondas predeterminadas ───────────────────────────────────────────
drop table if exists _0075_estado;
create temp table _0075_estado (paso int, asignatura text, estado text, detalle text);

do $$
declare
  f record; c record; m record;
  v_ronda int; v_cd jsonb; v_mod_ronda text;
begin
  for f in
    select * from (values
    ('matematicas', 'Matemáticas', (select coalesce(parent_course_id, id) from public.courses where id = '88136e1a-4564-45bd-b514-0ad6690b182c'::uuid),
      $mat1${"bank":"matematicas","bankRound":1,"passingScore":0,"questions":[{"id":"mat-01","question":"Un agricultor tiene un terreno rectangular de 20 metros de ancho y 30 metros de largo. Decide construir un invernadero que ocupe el 40% del área total del terreno. Para saber si el invernadero cabe, calcula el área y afirma: \"El invernadero tendrá un área de 240 metros cuadrados, por lo tanto, es más pequeño que el terreno\".\n¿Es correcta la afirmación del agricultor?","options":["Sí, porque 240 m² es menor que 600 m² (el área total del terreno).","No, porque el 40 % de 600 m² es 360 m², no 240 m².","Sí, porque al calcular el 40% de 30 metros (el lado más largo), obtiene 12 metros, y al multiplicarlo por 20, da 240 m².","No, porque el agricultor debió calcular el área del invernadero como el 40% del largo más el 40% del ancho."],"correct":0,"hint":"Calcula el área total y su 40 %: ¿el resultado contradice lo que dice el agricultor?","difficulty":"facil","timeLimit":60,"explanation":"El área del terreno es 20 × 30 = 600 m² y el 40 % de 600 es 240 m². Como 240 < 600, el invernadero cabe y la afirmación es correcta. B calcula mal el porcentaje, C toma el 40 % de un solo lado (llega a 240 por casualidad, con un razonamiento incorrecto) y D suma porcentajes de los lados, que no es como se calcula un área."},{"id":"mat-02","question":"En una heladería, se ofrecen tres tamaños de conos: pequeño, mediano y grande. La siguiente tabla muestra la relación entre el diámetro de la base y la altura de cada cono, que son proporcionales.\nTamaño | Diámetro (cm) | Altura (cm)\nPequeño | 3 | 6\nMediano | 4,5 | 9\nGrande | 6 | 12\nSi el volumen de un cono se calcula con la fórmula V = (1/3)πr²h (donde r es el radio), un estudiante afirma: \"El cono grande tiene el doble del volumen del cono pequeño\". ¿Es correcta esta afirmación?","options":["Sí, porque la altura y el diámetro del cono grande son el doble de los del cono pequeño.","Sí, porque el volumen es directamente proporcional a la altura y al cuadrado del radio.","No, porque el factor de escala entre los conos es 3/2, no 2.","No, porque si el diámetro y la altura se duplican, el volumen se multiplica por 8 (2 x 2²)."],"correct":3,"hint":"El radio va al cuadrado en la fórmula: si se duplica, ¿por cuánto se multiplica r²·h?","difficulty":"media","timeLimit":60,"explanation":"El cono grande tiene el doble de diámetro (6 vs 3 cm) y de altura (12 vs 6 cm) que el pequeño. Si el radio se duplica, r² se multiplica por 4, y la altura por 2: el volumen se multiplica por 2 × 2² = 8, no por 2. Por eso la afirmación es incorrecta."},{"id":"mat-03","question":"Una empresa de mensajería cobra por sus servicios de la siguiente manera: un costo fijo de $5.000 por recogida y $2.500 por cada kilómetro recorrido. La distancia recorrida para un paquete es de 12 km. Para calcular el costo total, un empleado realizó el siguiente procedimiento:\nPaso 1. Multiplicó la distancia (12 km) por el costo por kilómetro ($2.500).\nPaso 2. Al resultado del paso 1 ($30.000), le sumó el costo fijo de recogida ($5.000).\nPaso 3. Obtuvo un costo total de $35.000.\nUn cliente afirma que el costo debería ser $37.500, ya que el costo fijo también debería multiplicarse por los kilómetros. ¿Quién tiene razón?","options":["El cliente, porque el costo fijo también depende de la distancia recorrida.","El empleado, porque la tarifa es un costo fijo más un costo variable por kilómetro; el costo fijo no se multiplica por la distancia.","El cliente, porque el costo total es el promedio entre el costo fijo y el costo variable.","El empleado, porque el costo por kilómetro es $2.500, por lo que para 12 km el costo variable es $30.000 y el total es $35.000, pero el cliente se equivocó al calcular el costo variable."],"correct":1,"hint":"Pregúntate qué parte de la tarifa cambia con los kilómetros y cuál se cobra una sola vez.","difficulty":"dificil","timeLimit":60,"explanation":"El modelo de negocio es Costo Total = Costo Fijo + Costo Variable * Distancia. El costo fijo de $5.000 se cobra una sola vez, independientemente de la distancia."},{"id":"mat-04","question":"En un mapa, se indica que la escala es de 1:50.000. Esto significa que 1 centímetro en el mapa representa 50.000 centímetros en la realidad. Para determinar la distancia real entre dos ciudades que están a 8 cm de distancia en el mapa, un estudiante realiza el siguiente cálculo:\n8 cm * 50.000 = 400.000 cm\nLuego, convierte el resultado: 400.000 cm = 4.000 m = 4 km.\nUn compañero de clase argumenta que, debido a que el mapa es una representación, la distancia real debe ser mayor y propone multiplicar 8 cm por 50.000 y luego por 1.000 para convertir a kilómetros, obteniendo 400.000 km. ¿Quién tiene la razón?","options":["El primer estudiante, porque su proceso de conversión es correcto: 400.000 cm equivalen a 4 km.","El segundo estudiante, porque para convertir centímetros a kilómetros se debe multiplicar por 100.000, y él lo hizo.","El primer estudiante, porque el cálculo de 400.000 cm es incorrecto, pero su resultado en km es correcto.","El segundo estudiante, porque la escala indica que la distancia real es mucho mayor que la que se muestra en el mapa."],"correct":0,"hint":"Recuerda que 1 km = 100.000 cm. Convierte y mira cuál de los dos resultados tiene sentido.","difficulty":"dificil","timeLimit":60,"explanation":"El primer estudiante es correcto. 50.000 cm en la realidad son 0.5 km. 8 * 0.5 = 4 km. El proceso de conversión (400.000 cm = 4.000 m = 4 km) es correcto."},{"id":"mat-05","question":"La siguiente gráfica muestra el número de visitantes que tuvo un museo durante los primeros cinco meses del año.\nUn analista afirma: \"Entre febrero y marzo, el número de visitantes se redujo a la mitad\". ¿Por qué esta afirmación es incorrecta?","options":["Porque la gráfica muestra un descenso de 7 a 5 visitantes, lo que no es la mitad.","Porque el descenso fue de 2.000 visitantes, lo que es menos de la mitad.","Porque el descenso fue de 2 visitantes, y la mitad de 7 es 3,5.","Porque la gráfica muestra que el número de visitantes en marzo es 5, y la mitad de 7 es 3,5, por lo que no se redujo a la mitad."],"correct":3,"hint":"Lee en la gráfica el valor de febrero y el de marzo (en miles) y calcula la mitad del primero.","difficulty":"dificil","timeLimit":75,"image":"/preguntas/matematicas/visitantes-museo.jpg","explanation":"Un descenso a la mitad significaría que el valor final es la mitad del inicial. El valor inicial (febrero) es 7, la mitad sería 3.5, pero el valor en marzo es 5. Por lo tanto, el descenso no fue a la mitad."},{"id":"mat-06","question":"Un videojuego tiene una mecánica de puntuación que sigue la siguiente regla: Por cada nivel superado, el jugador gana puntos equivalentes al nivel multiplicado por 100, más un bono de 200 puntos. Es decir, la puntuación para el nivel n es P(n) = 100n + 200.\n¿Cuál es la diferencia de puntuación entre el nivel 8 y el nivel 5?","options":["300 puntos","500 puntos","800 puntos","100 puntos"],"correct":0,"hint":"Calcula P(8) y P(5) por separado… ¿qué le pasa al bono de 200 cuando restas?","difficulty":"facil","timeLimit":60,"explanation":"La diferencia es P(8) - P(5) = (100*8 + 200) - (100*5 + 200) = 1000 - 700 = 300 puntos."},{"id":"mat-07","question":"Se tiene un triángulo rectángulo en el que uno de sus ángulos agudos mide 30° y el cateto opuesto a este ángulo mide 6 cm. Un estudiante utiliza la relación trigonométrica sen(30°) = 6/hipotenusa para encontrar la hipotenusa.\nSabiendo que sen(30°) = 1/2, ¿cuál es la longitud de la hipotenusa?","options":["3 cm","6 cm","9 cm","12 cm"],"correct":3,"hint":"Seno = cateto opuesto ÷ hipotenusa. Si ese cociente es 1/2, ¿cuántas veces cabe el cateto en la hipotenusa?","difficulty":"facil","timeLimit":60,"explanation":"La fórmula es sen(30°) = cateto opuesto / hipotenusa. Sustituyendo: 1/2 = 6 / hipotenusa. Por lo tanto, hipotenusa = 6 * 2 = 12 cm."},{"id":"mat-08","question":"En un colegio, el 40% de los estudiantes participan en el club de ciencias, el 25% en el club de deportes y el 15% participan en ambos clubes.\nUn estudiante, para saber cuántos estudiantes participan en al menos uno de los dos clubes, propone el siguiente razonamiento: \"Se debe sumar el porcentaje de los que están en ciencias y el de los que están en deportes y restar el porcentaje de los que están en ambos\". El resultado de este razonamiento es:","options":["65%, que corresponde a 40% + 25%.","50%, que corresponde a 40% + 25% - 15%.","80%, que corresponde a 40% + 25% + 15%.","15%, que corresponde a 40% - 25%."],"correct":1,"hint":"Al sumar los dos clubes, quienes están en ambos quedan contados dos veces.","difficulty":"dificil","timeLimit":60,"explanation":"Para encontrar los que están en al menos uno de los conjuntos (unión), se debe sumar los que están en cada conjunto (40% + 25%) y restar la intersección (15%) para no contar a los que pertenecen a ambos dos veces. El resultado es 50%."},{"id":"mat-09","question":"Para un proyecto de arte, se necesita dividir una cartulina rectangular de 120 cm de largo y 80 cm de ancho en cuadrados del mayor tamaño posible, sin que sobre material. Cada cuadrado debe tener un lado de longitud exacta en centímetros.\n¿Cuál debe ser la longitud del lado de cada cuadrado?","options":["10 cm","20 cm","30 cm","40 cm"],"correct":3,"hint":"Buscas el número más grande que divida exactamente a 120 y a 80.","difficulty":"dificil","timeLimit":60,"explanation":"El problema pide el máximo común divisor (MCD) de 120 y 80. El MCD(120, 80) es 40 cm, que es el lado del cuadrado más grande que cabe de forma exacta."},{"id":"mat-10","question":"Un grupo de 5 amigos compró boletas para una función de cine. Los precios de las boletas fueron: $12.000, $10.500, $11.000, $12.500 y $11.500. Deciden que cada uno debe pagar el mismo valor, por lo que calculan el promedio.\n¿Cuál es el valor que debe pagar cada uno?","options":["$11.000","$11.500","$12.000","$12.500"],"correct":1,"hint":"Suma los cinco precios y reparte en partes iguales entre los 5 amigos.","difficulty":"dificil","timeLimit":60,"explanation":"El promedio se calcula sumando todos los valores y dividiendo por el número de datos (5). La suma es 57.500, y al dividir entre 5 da $11.500."}]}$mat1$::jsonb,
      $mat2${"bank":"matematicas","bankRound":2,"passingScore":0,"questions":[{"id":"mat-11","question":"La siguiente tabla muestra el número de suscriptores de una plataforma digital durante cuatro meses consecutivos.\nMes | Suscriptores (en miles)\nEnero | 150\nFebrero | 180\nMarzo | 210\nAbril | 240\nUn analista afirma que el número de suscriptores sigue una función lineal y propone la fórmula S(m) = 30m + 150, donde m es el mes (Enero = 1). ¿Es correcta esta afirmación?","options":["Sí, porque el incremento mensual es constante (30.000) y la fórmula coincide con los datos de la tabla.","No, porque la función debería ser exponencial, ya que los suscriptores aumentan cada mes.","Sí, porque la fórmula predice correctamente el número de suscriptores para cualquier mes.","No, porque en la tabla el incremento no es constante."],"correct":0,"hint":"Revisa si el aumento de un mes a otro es siempre el mismo y prueba la fórmula con m = 1 y m = 2.","difficulty":"media","timeLimit":60,"explanation":"La relación es lineal porque el incremento entre meses es constante: 30 (miles). La fórmula S(m) = 30m + 150 da como resultado 180 para m=2, 210 para m=3, etc. Es correcta."},{"id":"mat-12","question":"En una bolsa hay 4 canicas rojas, 3 canicas azules y 5 canicas verdes. Se extraen dos canicas al azar, sin reemplazo (es decir, no se devuelve la primera canica a la bolsa).\n¿Cuál es la probabilidad de que la primera canica sea roja y la segunda sea azul?","options":["12/144","4/12","12/132","3/11"],"correct":2,"hint":"Después de sacar la primera canica, ¿cuántas quedan en la bolsa? Multiplica las dos probabilidades.","difficulty":"dificil","timeLimit":60,"explanation":"La probabilidad de que la primera sea roja es 4/12. Como no hay reemplazo, para la segunda extracción quedan 11 canicas, de las cuales 3 son azules. Por lo tanto, la probabilidad es (4/12) * (3/11) = 12/132."},{"id":"mat-13","question":"Un terreno tiene forma de triángulo rectángulo. Sus catetos miden 9 metros y 12 metros. Para cercarlo, se necesita conocer la longitud del lado más largo (la hipotenusa). Un estudiante aplica el teorema de Pitágoras y obtiene que la hipotenusa mide 15 metros.\nSi se aumenta la longitud de ambos catetos en un 20%, ¿cuál será la nueva medida de la hipotenusa?","options":["15 metros","16,2 metros","18 metros","21,6 metros"],"correct":2,"hint":"Si ambos catetos crecen en la misma proporción, la hipotenusa crece en esa misma proporción.","difficulty":"dificil","timeLimit":60,"explanation":"Al aumentar ambos catetos en un 20%, el triángulo resultante es semejante al original con factor de escala 1.2. Por lo tanto, la nueva hipotenusa es 15 * 1.2 = 18 metros."},{"id":"mat-14","question":"Una tienda de ropa ofrece un descuento del 30% en todos sus productos. Adicionalmente, por ser cliente frecuente, se aplica un descuento adicional del 10% sobre el precio ya rebajado.\nUn cliente quiere comprar una chaqueta cuyo precio original es de $200.000. Para calcular cuánto debe pagar, realiza el siguiente procedimiento:\n1. Calcula el 30% de $200.000 = $60.000.\n2. Resta ese valor del precio original: $200.000 - $60.000 = $140.000.\n3. Calcula el 10% de $140.000 = $14.000.\n4. Resta ese valor: $140.000 - $14.000 = $126.000.\nUn amigo le dice que el descuento total es del 40%, por lo que debería pagar $120.000. ¿Quién tiene la razón?","options":["El cliente, porque los descuentos sucesivos no se suman.","El amigo, porque el 30% + 10% = 40% de descuento.","El cliente, porque su procedimiento es incorrecto.","El amigo, porque el descuento total siempre es la suma de los descuentos individuales."],"correct":0,"hint":"El segundo descuento se calcula sobre el precio ya rebajado, no sobre el original.","difficulty":"dificil","timeLimit":60,"explanation":"El cliente tiene razón. Los descuentos sucesivos no se suman, sino que se aplican uno sobre el valor resultante del otro. El descuento total es del 37% (1 - (0.7 * 0.9) = 1 - 0.63 = 0.37), no del 40%. Por lo tanto, el precio final es de $126.000."},{"id":"mat-15","question":"En una empresa, se deben asignar 3 puestos de trabajo diferentes (Gerente, Subgerente y Asistente) a 5 candidatos calificados. ¿De cuántas maneras diferentes se pueden ocupar los puestos?","options":["15","60","125","10"],"correct":1,"hint":"Los puestos son distintos, así que el orden importa: ¿cuántos pueden ser gerente, luego subgerente, luego asistente?","difficulty":"media","timeLimit":60,"explanation":"Es una permutación, ya que el orden importa (los puestos son diferentes). Se calcula como 5P3 = 5! / (5-3)! = 5*4*3 = 60."},{"id":"mat-16","question":"En un colegio, las calificaciones de los estudiantes se calculan con una media ponderada: el 70% corresponde al examen final y el 30% al trabajo práctico.\nUn estudiante obtuvo 4.5 en el trabajo práctico y 3.8 en el examen final. ¿Cuál es su calificación definitiva?","options":["4.0","3.8","4.15","4.01"],"correct":3,"hint":"Multiplica cada nota por su porcentaje: el 70 % va con el examen final.","difficulty":"dificil","timeLimit":60,"explanation":"La media ponderada se calcula como (0.3 * 4.5) + (0.7 * 3.8) = 1.35 + 2.66 = 4.01."},{"id":"mat-17","question":"Se tiene un cuadrado de lado 4 cm. Al unir los puntos medios de sus lados, se forma un nuevo cuadrado inscrito.\n¿Cuál es el área del cuadrado inscrito?","options":["16 cm²","8 cm²","4 cm²","2 cm²"],"correct":1,"hint":"Mira la figura: los cuatro triángulos blancos de las esquinas, ¿qué parte del cuadrado grande ocupan juntos?","difficulty":"media","timeLimit":75,"image":"/preguntas/matematicas/cuadrado-inscrito.jpg","explanation":"El cuadrado inscrito tiene lados que son la mitad de la diagonal del cuadrado grande, o bien, el área del cuadrado grande es 16 cm². Al unir puntos medios, el cuadrado inscrito ocupa exactamente la mitad del área, por lo tanto, 8 cm²."},{"id":"mat-18","question":"La siguiente gráfica de barras muestra la cantidad de libros vendidos en una librería durante los tres primeros meses del año.\n¿Cuál de las siguientes afirmaciones es FALSA con respecto a la información de la gráfica?","options":["En febrero se vendieron 20 libros más que en enero.","En marzo se vendió la mitad de lo que se vendió en febrero.","El promedio de libros vendidos en los tres meses es 60.","En enero y marzo se vendieron la misma cantidad de libros."],"correct":3,"hint":"Lee el valor exacto de cada barra y verifica afirmación por afirmación: buscas la que NO se cumple.","difficulty":"facil","timeLimit":75,"image":"/preguntas/matematicas/libros-vendidos.jpg","explanation":"La afirmación falsa es la D. En enero se vendieron 60 libros y en marzo 40, por lo tanto, no se vendió la misma cantidad."},{"id":"mat-19","question":"Un grupo de estudiantes debe resolver la siguiente ecuación:\n2(x − 3) = 4x + 2\nCuatro estudiantes proponen los siguientes primeros pasos para despejar la incógnita:\n• Ana: Dividir ambos lados de la ecuación entre 2.\n• Luis: Restar 2 a ambos lados.\n• Marta: Multiplicar ambos lados por 2.\n• Carlos: Sumar 3 a ambos lados.\n¿Cuál de estos estudiantes NO está aplicando una propiedad de la igualdad que mantenga la solución de la ecuación?","options":["Ana","Luis","Marta","Carlos"],"correct":2,"hint":"Piensa qué operación no te acerca a despejar la x, aunque se haga a ambos lados.","difficulty":"facil","timeLimit":60,"explanation":"Para resolver ecuaciones, se debe buscar aislar la variable. Multiplicar ambos lados por 2 solo complicaría la ecuación (la convertiría en 4(x-3) = 8x + 4), no es un paso estándar para despejar la incógnita de manera eficiente. Las operaciones de Ana, Luis y Carlos sí son pasos válidos y permiten simplificar la ecuación."},{"id":"mat-20","question":"La figura muestra un rectángulo de 8 cm de ancho y 6 cm de alto. En su interior se ha dibujado una línea quebrada de color azul: parte del lado izquierdo, 2 cm por debajo del borde superior, avanza 5 cm hacia la derecha y luego baja en línea recta hasta el borde inferior.\n¿Cuál es la longitud total de la línea quebrada de color azul?","options":["9 cm","14 cm","11 cm","7 cm"],"correct":0,"hint":"Mide cada tramo por separado: ¿desde qué altura empieza el tramo que baja?","difficulty":"dificil","timeLimit":75,"image":"/preguntas/matematicas/linea-quebrada.jpg","explanation":"La línea tiene dos tramos: uno horizontal de 5 cm y uno vertical que baja desde 2 cm por debajo del borde superior hasta el borde inferior, es decir 6 − 2 = 4 cm. En total: 5 + 4 = 9 cm. 14 cm (8 + 6) solo sería cierto si la línea recorriera el ancho y el alto completos del rectángulo."}]}$mat2$::jsonb),
    ('lectura', 'Lenguaje', (select coalesce(parent_course_id, id) from public.courses where id = 'd4aa2014-aa49-46d1-8ac3-7e5842fc8dc1'::uuid),
      $lec1${"bank":"lectura","bankRound":1,"passingScore":0,"questions":[{"id":"lec-01","question":"En el último párrafo del texto se utiliza la palabra \"famélico\" para describir a Johnny. ¿Cuál de los siguientes adjetivos le da un sentido contrario al significado que tiene esta palabra en el texto?","options":["Magro.","Enjuto.","Relleno.","Esquelético."],"correct":2,"hint":"“Famélico” viene de “hambre”: busca la palabra que signifique lo contrario de muy flaco.","difficulty":"dificil","timeLimit":120,"explanation":"Competencia que evalúa: identifica y entiende los contenidos locales que conforman un texto.","passage":{"intro":"RESPONDE LAS PREGUNTAS 1 A 3 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","title":"JOHNNY","paragraphs":["«Conozco a un tipo»: Esta es la frase recurrente que define a Johnny. A secas. Johnny era así, uno le decía: me encantaría multiplicar mis ahorros por mil. Y él: \"Conozco a un tipo\". Me encantaría viajar a Cuba, comprar unos habanos y volver. ¿Para qué? Para venderlo. \"Conozco a un tipo\".","Me encantaría hacerme un tatuaje. ¿Dónde? En la nuca: \"Conozco a un tipo\"","Me encantaría quedarme acá para siempre. Y ahí Johnny ya no conocía a nadie. Decía: este es un país muy duro. Pero él vivía como un magnate, cambiaba de carro cada seis meses y seguía pagando el mismo leasing; cobraba un subsidio de desempleo que nadie le controlaba y era con eso que pagaba los moteles donde tirábamos, o las langostas que nos comíamos en Key West, o los VIP passes de los bares de salsa a los que le gustaba llevarme en Calle Ocho.","Johnny vivía a expensas de su mujer –mitad gringa, mitad ecuatoriana– y compraba hasta los calzoncillos de marca: alimentaba rigurosamente su pequeño sueño americano como si temiera que, si un día se olvidaba de hacerlo, se desplomara a sus pies como un pajarito famélico."],"source":"Tomado y adaptado de: García Robayo, M. (2015). Hasta que pase un huracán. Bogotá, D. C.: Laguna Libros."}},{"id":"lec-02","question":"El fragmento lo narra","options":["Un testigo que solo cuenta lo que ve.","Johnny, el protagonista.","Un personaje de la historia que cuenta lo que le contaron.","Alguien que conoce a Johnny."],"correct":3,"hint":"Fíjate en los pronombres: “…le gustaba llevarme…”. ¿Quién está hablando?","difficulty":"dificil","timeLimit":120,"explanation":"Competencia que evalúa: comprende cómo se articulan las partes de un texto para darle un sentido global.","passage":{"intro":"RESPONDE LAS PREGUNTAS 1 A 3 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","title":"JOHNNY","paragraphs":["«Conozco a un tipo»: Esta es la frase recurrente que define a Johnny. A secas. Johnny era así, uno le decía: me encantaría multiplicar mis ahorros por mil. Y él: \"Conozco a un tipo\". Me encantaría viajar a Cuba, comprar unos habanos y volver. ¿Para qué? Para venderlo. \"Conozco a un tipo\".","Me encantaría hacerme un tatuaje. ¿Dónde? En la nuca: \"Conozco a un tipo\"","Me encantaría quedarme acá para siempre. Y ahí Johnny ya no conocía a nadie. Decía: este es un país muy duro. Pero él vivía como un magnate, cambiaba de carro cada seis meses y seguía pagando el mismo leasing; cobraba un subsidio de desempleo que nadie le controlaba y era con eso que pagaba los moteles donde tirábamos, o las langostas que nos comíamos en Key West, o los VIP passes de los bares de salsa a los que le gustaba llevarme en Calle Ocho.","Johnny vivía a expensas de su mujer –mitad gringa, mitad ecuatoriana– y compraba hasta los calzoncillos de marca: alimentaba rigurosamente su pequeño sueño americano como si temiera que, si un día se olvidaba de hacerlo, se desplomara a sus pies como un pajarito famélico."],"source":"Tomado y adaptado de: García Robayo, M. (2015). Hasta que pase un huracán. Bogotá, D. C.: Laguna Libros."}},{"id":"lec-03","question":"Desde la información que brinda el texto, ¿cuál de las siguientes palabras describe mejor a Johnny?","options":["Vividor.","Generoso.","Trabajador.","Mezquino."],"correct":0,"hint":"Johnny vive como magnate sin trabajar y a costa de otros. ¿Qué palabra resume eso?","difficulty":"media","timeLimit":120,"explanation":"Competencia que evalúa: identifica y entiende los contenidos locales que conforman un texto.","passage":{"intro":"RESPONDE LAS PREGUNTAS 1 A 3 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","title":"JOHNNY","paragraphs":["«Conozco a un tipo»: Esta es la frase recurrente que define a Johnny. A secas. Johnny era así, uno le decía: me encantaría multiplicar mis ahorros por mil. Y él: \"Conozco a un tipo\". Me encantaría viajar a Cuba, comprar unos habanos y volver. ¿Para qué? Para venderlo. \"Conozco a un tipo\".","Me encantaría hacerme un tatuaje. ¿Dónde? En la nuca: \"Conozco a un tipo\"","Me encantaría quedarme acá para siempre. Y ahí Johnny ya no conocía a nadie. Decía: este es un país muy duro. Pero él vivía como un magnate, cambiaba de carro cada seis meses y seguía pagando el mismo leasing; cobraba un subsidio de desempleo que nadie le controlaba y era con eso que pagaba los moteles donde tirábamos, o las langostas que nos comíamos en Key West, o los VIP passes de los bares de salsa a los que le gustaba llevarme en Calle Ocho.","Johnny vivía a expensas de su mujer –mitad gringa, mitad ecuatoriana– y compraba hasta los calzoncillos de marca: alimentaba rigurosamente su pequeño sueño americano como si temiera que, si un día se olvidaba de hacerlo, se desplomara a sus pies como un pajarito famélico."],"source":"Tomado y adaptado de: García Robayo, M. (2015). Hasta que pase un huracán. Bogotá, D. C.: Laguna Libros."}},{"id":"lec-04","question":"¿Cuál de las siguientes citas refuerza la idea de que el comportamiento de la avispa Sphex no resulta de un proceso de pensamiento racional?","options":["“La avispa lleva al grillo a su madriguera, deja sus huevos, cierra la madriguera y luego se va para no volver”.","“La avispa nunca piensa en llevar al grillo directamente a su madriguera. En una ocasión, este procedimiento fue repetido cuarenta veces, siempre con el mismo resultado”.","“Para la mente humana, tal rutina tan organizada y aparentemente llena de propósitos lleva consigo un sabor de lógica y de pensamiento”.","“Por ejemplo, la rutina de la avispa consiste en llevar al grillo hacia la madriguera, dejarlo en la entrada, ir adentro a revisar que todo esté bien, salir y luego dejar el grillo adentro”."],"correct":1,"hint":"Busca la cita que muestra una conducta repetida sin cambio, aunque no tenga sentido.","difficulty":"dificil","timeLimit":150,"explanation":"Competencia que evalúa: comprende cómo se articulan las partes de un texto para darle un sentido global.","passage":{"intro":"RESPONDE LAS PREGUNTAS 4 Y 5 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","title":"Instinto en lugar de lógica","paragraphs":["Cuando llega la hora de poner sus huevos, la avispa Sphex construye una pequeña madriguera para este propósito y sale en la búsqueda de un grillo al cual pica de manera tal que lo paraliza, pero no lo mata. La avispa lleva al grillo a su madriguera, deja sus huevos, cierra la madriguera y luego se va para no volver. Pasado un tiempo, los huevos crecen y la cría de la avispa se alimenta del grillo paralizado que no se descompone debido a que ha permanecido congelado. Para la mente humana, tal rutina tan organizada y aparentemente llena de propósitos lleva consigo un sabor de lógica y de pensamiento. O por lo menos esto es así hasta que conocemos más detalles.","Por ejemplo, la rutina de la avispa consiste en llevar al grillo hacia la madriguera, dejarlo en la entrada, ir adentro a revisar que todo esté bien, salir y luego dejar el grillo adentro. Si, mientras la avispa está dentro de la madriguera haciendo su inspección preliminar, el grillo es movido algunos centímetros de la entrada, entonces la avispa, al salir de la madriguera, volverá a dejar al grillo de nuevo en la entrada, pero no adentro, y repetirá el procedimiento preparatorio de entrar a la madriguera a revisar que todo esté bien. Si, de nuevo, el grillo es movido unos centímetros de la entrada, la avispa llevará otra vez al grillo hacia la entrada y volverá a entrar a la madriguera para revisarla. La avispa nunca piensa en llevar al grillo directamente a su madriguera. En una ocasión, este procedimiento fue repetido cuarenta veces, siempre con el mismo resultado."],"source":"Tomado y adaptado de: Woolridge, Dean E. (1963). The Machinery of the Brain, New York: McGraw-Hill, pp. 82-83."}},{"id":"lec-05","question":"¿Cuál de los siguientes enunciados sintetiza el tema principal del texto?","options":["El comportamiento aparentemente inteligente de la avispa Sphex.","El papel de los grillos en la alimentación de las avispas Sphex.","La avispa Sphex como un caso que prueba la inteligencia animal.","Los métodos de crianza y las precauciones de las avispas Sphex."],"correct":0,"hint":"El título da la pista: ¿la avispa piensa o sigue un instinto?","difficulty":"media","timeLimit":150,"explanation":"Competencia que evalúa: comprende cómo se articulan las partes de un texto para darle un sentido global.","passage":{"intro":"RESPONDE LAS PREGUNTAS 4 Y 5 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","title":"Instinto en lugar de lógica","paragraphs":["Cuando llega la hora de poner sus huevos, la avispa Sphex construye una pequeña madriguera para este propósito y sale en la búsqueda de un grillo al cual pica de manera tal que lo paraliza, pero no lo mata. La avispa lleva al grillo a su madriguera, deja sus huevos, cierra la madriguera y luego se va para no volver. Pasado un tiempo, los huevos crecen y la cría de la avispa se alimenta del grillo paralizado que no se descompone debido a que ha permanecido congelado. Para la mente humana, tal rutina tan organizada y aparentemente llena de propósitos lleva consigo un sabor de lógica y de pensamiento. O por lo menos esto es así hasta que conocemos más detalles.","Por ejemplo, la rutina de la avispa consiste en llevar al grillo hacia la madriguera, dejarlo en la entrada, ir adentro a revisar que todo esté bien, salir y luego dejar el grillo adentro. Si, mientras la avispa está dentro de la madriguera haciendo su inspección preliminar, el grillo es movido algunos centímetros de la entrada, entonces la avispa, al salir de la madriguera, volverá a dejar al grillo de nuevo en la entrada, pero no adentro, y repetirá el procedimiento preparatorio de entrar a la madriguera a revisar que todo esté bien. Si, de nuevo, el grillo es movido unos centímetros de la entrada, la avispa llevará otra vez al grillo hacia la entrada y volverá a entrar a la madriguera para revisarla. La avispa nunca piensa en llevar al grillo directamente a su madriguera. En una ocasión, este procedimiento fue repetido cuarenta veces, siempre con el mismo resultado."],"source":"Tomado y adaptado de: Woolridge, Dean E. (1963). The Machinery of the Brain, New York: McGraw-Hill, pp. 82-83."}},{"id":"lec-06","question":"De acuerdo con la infografía, ¿en qué momento se requiere proceder a efectuar una reanimación cardíaca?","options":["Después de confirmar que la víctima reacciona.","Después de comprobar que la víctima no tiene pulso.","En el momento en que la víctima muestra problemas de respiración.","En el momento en que la víctima está en posición de recuperación."],"correct":1,"hint":"Sigue el orden de los pasos: el masaje cardíaco va después de comprobar algo.","difficulty":"dificil","timeLimit":120,"explanation":"Competencia que evalúa: comprende cómo se articulan las partes de un texto para darle un sentido global.","passage":{"intro":"RESPONDE LAS PREGUNTAS 6 A 8 DE ACUERDO CON EL SIGUIENTE CONTEXTO","images":[{"url":"/preguntas/lectura/rcp-infografia.jpg"}]}},{"id":"lec-07","question":"En caso de que la víctima no respire, ¿qué procedimiento se sugiere seguir en la infografía?","options":["Saltar al paso 5 (tomar el pulso).","Llamar a un número de emergencias.","Realizar una respiración boca a boca.","Llevar a cabo una reanimación cardiopulmonar."],"correct":2,"hint":"Ubica en la infografía el paso que empieza con “Si no respira…”.","difficulty":"dificil","timeLimit":120,"explanation":"Competencia que evalúa: comprende cómo se articulan las partes de un texto para darle un sentido global.","passage":{"intro":"RESPONDE LAS PREGUNTAS 6 A 8 DE ACUERDO CON EL SIGUIENTE CONTEXTO","images":[{"url":"/preguntas/lectura/rcp-infografia.jpg"}]}},{"id":"lec-08","question":"De acuerdo con el propósito del texto, ¿cuál de las siguientes opciones NO presenta una buena razón para incluir imágenes en la infografía?","options":["La descripción verbal se debe acompañar de un ejemplo gráfico.","Se debe ilustrar en qué lugares se puede llevar a cabo la reanimación.","Se le debe aclarar al lector qué debe hacer en cada etapa de la reanimación.","Se deben representar los pasos que debe realizar una persona para reanimar a otra."],"correct":1,"hint":"Pregúntate qué NO necesita ilustrar una guía de primeros auxilios.","difficulty":"media","timeLimit":120,"explanation":"Competencia que evalúa: reflexiona a partir de un texto y evalúa su contenido.","passage":{"intro":"RESPONDE LAS PREGUNTAS 6 A 8 DE ACUERDO CON EL SIGUIENTE CONTEXTO","images":[{"url":"/preguntas/lectura/rcp-infografia.jpg"}]}},{"id":"lec-13","question":"En la historieta, el niño intenta justificar el alto precio de la limonada recurriendo a:","options":["Argumentos absurdos pero consistentes.","Un modelo económico fiel a la realidad.","Una ley de mercado que no existe.","Su propia versión de la economía."],"correct":3,"hint":"El niño inventa justificaciones que le convienen: ¿es economía real o su propia versión?","difficulty":"dificil","timeLimit":120,"explanation":"Competencia que evalúa: reflexiona a partir de un texto y evalúa su contenido.","passage":{"intro":"RESPONDE LA PREGUNTA 13 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","images":[{"url":"/preguntas/lectura/calvin-limonada.jpg"}]}},{"id":"lec-14","question":"¿Cuál de los siguientes enunciados describe mejor la caricatura?","options":["El pueblo hace justicia por su propia mano.","El linchamiento de un ángel.","Entrevista con el asesino.","Un ángel bajó del cielo."],"correct":1,"hint":"Mira la figura tendida en el piso: tiene alas. ¿Qué le hizo la multitud?","difficulty":"dificil","timeLimit":120,"explanation":"Competencia que evalúa: identifica y entiende los contenidos locales que conforman un texto.","passage":{"intro":"RESPONDE LA PREGUNTA 14 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","images":[{"url":"/preguntas/lectura/quino-angel.jpg"}]}}]}$lec1$::jsonb,
      $lec2${"bank":"lectura","bankRound":2,"passingScore":0,"questions":[{"id":"lec-15","question":"Teniendo en cuenta la información que brinda el texto, ¿cuál de las siguientes afirmaciones es compatible con las políticas del Partido?","options":["El pueblo debe mantenerse unido.","La individualidad debe ser eliminada.","El poder está en ser fiel a uno mismo.","Un pueblo ignorante es más poderoso."],"correct":1,"hint":"El Partido no permite lealtad, amor ni arte… salvo hacia él. ¿Qué queda de cada persona?","difficulty":"dificil","timeLimit":105,"explanation":"Competencia que evalúa: comprende cómo se articulan las partes de un texto para darle un sentido global.","passage":{"intro":"RESPONDE LAS PREGUNTAS 15 Y 16 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","title":"Gran Hermano","paragraphs":["1984 es una novela futurista que tiene lugar en una sociedad totalitaria. Los ciudadanos de esta sociedad son controlados por una figura omnipresente conocida como el Gran Hermano. En el siguiente apartado, un miembro defensor del orden le explica al protagonista el principal propósito del régimen.","No habrá lealtad; no existirá más fidelidad que la que se debe al Partido, ni más amor que el amor al Gran Hermano. No habrá risa, excepto la risa triunfal cuando se derrota a un enemigo. No habrá arte, ni literatura, ni ciencia. No habrá ya distinción entre la belleza y la fealdad. Todos los placeres serán destruidos. Pero siempre, no lo olvides, Winston, siempre habrá el afán de poder, la sed de dominio, que aumentará constantemente y se hará cada vez más sutil. Siempre existirá la emoción de la victoria, la sensación de pisotear a un enemigo indefenso. Si quieres hacerte una idea de cómo será el futuro, figúrate una bota aplastando un rostro humano... incesantemente."],"source":"Tomado y adaptado de: Orwell, George. 1984. Barcelona: Ediciones Destino. 2008."}},{"id":"lec-16","question":"En el texto, la frase “figúrate una bota aplastando un rostro humano…incesantemente”","options":["explica los planes para el futuro del régimen.","ejemplifica las ideas transmitidas al pueblo.","expone el verdadero propósito del sistema de gobierno.","ilustra las condiciones de los ciudadanos bajo el régimen."],"correct":3,"hint":"La imagen de la bota no es un plan: describe cómo vivirán las personas bajo ese poder.","difficulty":"dificil","timeLimit":105,"explanation":"Competencia que evalúa: comprende cómo se articulan las partes de un texto para darle un sentido global.","passage":{"intro":"RESPONDE LAS PREGUNTAS 15 Y 16 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","title":"Gran Hermano","paragraphs":["1984 es una novela futurista que tiene lugar en una sociedad totalitaria. Los ciudadanos de esta sociedad son controlados por una figura omnipresente conocida como el Gran Hermano. En el siguiente apartado, un miembro defensor del orden le explica al protagonista el principal propósito del régimen.","No habrá lealtad; no existirá más fidelidad que la que se debe al Partido, ni más amor que el amor al Gran Hermano. No habrá risa, excepto la risa triunfal cuando se derrota a un enemigo. No habrá arte, ni literatura, ni ciencia. No habrá ya distinción entre la belleza y la fealdad. Todos los placeres serán destruidos. Pero siempre, no lo olvides, Winston, siempre habrá el afán de poder, la sed de dominio, que aumentará constantemente y se hará cada vez más sutil. Siempre existirá la emoción de la victoria, la sensación de pisotear a un enemigo indefenso. Si quieres hacerte una idea de cómo será el futuro, figúrate una bota aplastando un rostro humano... incesantemente."],"source":"Tomado y adaptado de: Orwell, George. 1984. Barcelona: Ediciones Destino. 2008."}},{"id":"lec-17","question":"En el fragmento tomado del texto: “Las fotografías son la prueba irrecusable de que se hizo la excursión, se cumplió el programa, se gozó del viaje”, ¿cuál de las siguientes palabras es un sinónimo de la palabra ‘irrecusable’?","options":["Inminente.","Concluyente.","Irremplazable.","Cuestionable."],"correct":1,"hint":"“Irrecusable” es algo que no se puede rechazar ni refutar.","difficulty":"media","timeLimit":180,"explanation":"Competencia que evalúa: identifica y entiende los contenidos locales que conforman un texto.","passage":{"intro":"RESPONDE LAS PREGUNTAS 17 Y 18 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","title":"Sobre la fotografía","paragraphs":["Si las fotografías permiten la posesión imaginaria de un pasado irreal, también ayudan a tomar posesión de un espacio donde la gente está insegura. Así, la fotografía se desarrolla en conjunción con una de las actividades modernas más características: el turismo. Por primera vez en la historia, grupos numerosos de gente abandonan sus entornos habituales por breves periodos. Parece decididamente anormal viajar por placer sin llevar una cámara. Las fotografías son la prueba irrecusable de que se hizo la excursión, se cumplió el programa, se gozó del viaje. Las fotografías documentan secuencias de consumo realizadas en ausencia de la familia, los amigos, los vecinos. Pero la dependencia de la cámara, en cuanto aparato que da realidad a las experiencias, no disminuye cuando la gente viaja más. El acto de fotografiar satisface las mismas necesidades para los cosmopolitas que acumulan trofeos fotográficos de su excursión en barco por el Nilo o sus catorce días en China, que para los turistas de clase media que hacen instantáneas de la Torre Eiffel o las cataratas del Niágara.","El acto fotográfico, un modo de certificar la experiencia, es también un modo de rechazarla: cuando se confina a la búsqueda de lo fotogénico, cuando se convierte la experiencia en una imagen, un recuerdo. El viaje se transforma en una estrategia para acumular fotos. La propia actividad fotográfica es tranquilizadora, y mitiga esa desorientación general que se suele agudizar con los viajes. La mayoría de los turistas se sienten obligados a poner la cámara entre ellos y toda cosa destacable que les sale al paso. Al no saber cómo reaccionar, hacen una foto. Así, la experiencia cobra forma: alto, una fotografía, adelante. El método seduce sobre todo a gente subyugada a una ética de trabajo implacable: alemanes, japoneses y estadounidenses. El empleo de una cámara atenúa su ansiedad provocada por la inactividad laboral cuando están en vacaciones y presuntamente divirtiéndose. Cuentan con una tarea que parece una simpática imitación del trabajo: pueden hacer fotos."],"source":"Tomado y adaptado de: Sontag, S. (2009). Sobre la fotografía. Barcelona: Debolsillo."}},{"id":"lec-18","question":"Considere el siguiente resumen del texto:\n“La autora analiza la relación entre el turismo y la fotografía, teniendo en cuenta que los cosmopolitas ven en sus viajes al acto de fotografiar como una necesidad. Según ella, ese acto acaba por convertirse en una práctica trivial con la que solo se busca mitigar la desorientación general que causan los viajes. Así, la fotografía se convierte para los cosmopolitas japoneses, estadounidenses y alemanes en una especie de reemplazo del trabajo al que están acostumbrados”.\nEl anterior resumen se puede describir como inadecuado porque","options":["expone ideas contrarias a las afirmaciones principales del texto.","se centra en un tipo particular de turistas y no en los turistas en general.","omite el tono irónico y burlón con que la autora se refiere al arte de la fotografía.","se detiene en presentar información en extremo detallada y secundaria del texto."],"correct":1,"hint":"El texto habla de los turistas en general; el resumen, de un grupo en particular.","difficulty":"media","timeLimit":180,"explanation":"Competencia que evalúa: comprende cómo se articulan las partes de un texto para darle un sentido global.","passage":{"intro":"RESPONDE LAS PREGUNTAS 17 Y 18 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","title":"Sobre la fotografía","paragraphs":["Si las fotografías permiten la posesión imaginaria de un pasado irreal, también ayudan a tomar posesión de un espacio donde la gente está insegura. Así, la fotografía se desarrolla en conjunción con una de las actividades modernas más características: el turismo. Por primera vez en la historia, grupos numerosos de gente abandonan sus entornos habituales por breves periodos. Parece decididamente anormal viajar por placer sin llevar una cámara. Las fotografías son la prueba irrecusable de que se hizo la excursión, se cumplió el programa, se gozó del viaje. Las fotografías documentan secuencias de consumo realizadas en ausencia de la familia, los amigos, los vecinos. Pero la dependencia de la cámara, en cuanto aparato que da realidad a las experiencias, no disminuye cuando la gente viaja más. El acto de fotografiar satisface las mismas necesidades para los cosmopolitas que acumulan trofeos fotográficos de su excursión en barco por el Nilo o sus catorce días en China, que para los turistas de clase media que hacen instantáneas de la Torre Eiffel o las cataratas del Niágara.","El acto fotográfico, un modo de certificar la experiencia, es también un modo de rechazarla: cuando se confina a la búsqueda de lo fotogénico, cuando se convierte la experiencia en una imagen, un recuerdo. El viaje se transforma en una estrategia para acumular fotos. La propia actividad fotográfica es tranquilizadora, y mitiga esa desorientación general que se suele agudizar con los viajes. La mayoría de los turistas se sienten obligados a poner la cámara entre ellos y toda cosa destacable que les sale al paso. Al no saber cómo reaccionar, hacen una foto. Así, la experiencia cobra forma: alto, una fotografía, adelante. El método seduce sobre todo a gente subyugada a una ética de trabajo implacable: alemanes, japoneses y estadounidenses. El empleo de una cámara atenúa su ansiedad provocada por la inactividad laboral cuando están en vacaciones y presuntamente divirtiéndose. Cuentan con una tarea que parece una simpática imitación del trabajo: pueden hacer fotos."],"source":"Tomado y adaptado de: Sontag, S. (2009). Sobre la fotografía. Barcelona: Debolsillo."}},{"id":"lec-21","question":"¿En cuál de los siguientes contextos se inscribe mejor la caricatura?","options":["Anuncio publicitario.","Reportaje gráfico.","Humor gráfico.","Sátira política."],"correct":2,"hint":"Pregúntate si la caricatura critica a un gobierno o se burla de una situación cotidiana.","difficulty":"media","timeLimit":120,"explanation":"Competencia que evalúa: reflexiona a partir de un texto y evalúa su contenido.","passage":{"intro":"RESPONDE LA PREGUNTA 21 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","images":[{"url":"/preguntas/lectura/quino-no-me-grite.jpg"}]}},{"id":"lec-29","question":"¿Cuál de las siguientes afirmaciones contradice las ideas que presenta el autor?","options":["Algunas personas actúan justamente a pesar de poder actuar de manera injusta.","La injusticia, contrariamente a la justicia, es natural en el ser humano.","Actuar con justicia brinda menos ventajas que hacerlo con injusticia.","La injusticia, contrariamente a la justicia, se comete voluntariamente."],"correct":0,"hint":"El autor sostiene que NADIE es justo por voluntad. ¿Qué afirmación lo niega?","difficulty":"dificil","timeLimit":180,"explanation":"Competencia que evalúa: reflexiona a partir de un texto y evalúa su contenido.","passage":{"intro":"RESPONDE LAS PREGUNTAS 29 A 33 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","title":"El Anillo de Giges: La Naturaleza de la Justicia","paragraphs":["Nadie es justo por voluntad sino porque no tiene el poder de cometer injusticias. Esto lo percibiremos mejor si nos imaginamos las cosas del siguiente modo: demos tanto al justo como al injusto el poder de hacer lo que cada uno de ellos quiere, y a continuación sigámoslos para observar hasta dónde lo lleva a cada uno el deseo. Entonces sorprenderemos al justo tomando el mismo camino que el injusto, siguiendo sus propios intereses, lo que toda criatura persigue por naturaleza como un bien, pero que la fuerza de la ley obliga a seguir el camino del respeto por la igualdad.","El poder del que hablo sería efectivo al máximo si aquellos hombres adquirieran una fuerza tal como la que se dice que cierta vez tuvo Giges, el antepasado del lidio. Giges era un pastor que servía al entonces rey de Lidia. Un día sobrevino una gran tormenta y un terremoto que rasgó la tierra y produjo un abismo en el lugar en que Giges llevaba el ganado a pastorear. Asombrado al ver esto, descendió al abismo y halló, entre otras maravillas que narran los mitos, un caballo de bronce, hueco y con ventanillas, a través de las cuales divisó adentro un cadáver de tamaño más grande que el de un hombre, según parecía, y que no tenía nada excepto un anillo de oro en la mano. Giges le quitó el anillo y salió del abismo. Ahora bien, los pastores hacían su reunión habitual para dar al rey el informe mensual concerniente a la hacienda, cuando llegó Giges llevando el anillo. Tras sentarse entre los demás, casualmente volvió el engaste del anillo hacia el interior de su mano. Al suceder esto se tornó invisible para los que estaban sentados allí, quienes se pusieron a hablar de él como si se hubiera ido. Giges se asombró, y luego, examinando el anillo, dio vuelta al engaste hacia afuera y tornó a hacerse visible. Al advertirlo, experimentó con el anillo para ver si tenía tal propiedad, y comprobó que así era: cuando giraba el engaste hacia adentro, su dueño se hacía invisible, y cuando lo giraba hacia afuera, se hacía visible. En cuanto se hubo cerciorado de ello, maquinó el modo de formar parte de los que fueron a la residencia del rey como informantes y, una vez allí, sedujo a la reina y con ayuda de ella mató al rey y se apoderó del reino.","Por consiguiente, si hubiese dos anillos como el de Giges y se diera uno a un hombre justo y otro a uno injusto, ninguno perseveraría en la justicia ni soportaría abstenerse de bienes ajenos, cuando podría tanto apoderarse impunemente de lo que quisiera del mercado, como, al entrar en las casas, acostarse con la mujer que prefiriera, y tanto matar a unos como librar de las cadenas a otros, según su voluntad, y hacer todo como si fuera igual a un dios entre los hombres. En esto, el hombre justo no haría nada diferente del injusto, sino que ambos marcharían por el mismo camino. E incluso se diría que esto es una importante prueba de que nadie es justo si no es forzado a serlo, por no considerarse a la justicia como un bien individual, ya que allí donde cada uno se cree capaz de cometer injusticias, las comete. En efecto, todo hombre piensa que la injusticia le brinda más ventajas individuales que la justicia, y está en lo cierto, si habla de acuerdo con esta teoría."],"source":"Tomado de: Platón IV, D. (1986). República, Traducción y notas de C. Eggers Lan, Madrid, Gredos."}},{"id":"lec-30","question":"De los siguientes enunciados, ¿cuál presenta un supuesto subyacente a la afirmación “Todo hombre piensa que la injusticia le brinda más ventajas individuales que la justicia, y está en lo cierto, si habla de acuerdo con esta teoría”?","options":["La injusticia brinda las mismas ventajas individuales que la justicia.","La justicia, al igual que la injusticia, brinda ventajas individuales.","La injusticia, a diferencia de la justicia, brinda pocas ventajas individuales.","La justicia no brinda ninguna de las ventajas individuales que la injusticia brinda."],"correct":1,"hint":"Decir que la injusticia da “más” ventajas supone que la justicia también da alguna.","difficulty":"media","timeLimit":180,"explanation":"Competencia que evalúa: reflexiona a partir de un texto y evalúa su contenido.","passage":{"intro":"RESPONDE LAS PREGUNTAS 29 A 33 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","title":"El Anillo de Giges: La Naturaleza de la Justicia","paragraphs":["Nadie es justo por voluntad sino porque no tiene el poder de cometer injusticias. Esto lo percibiremos mejor si nos imaginamos las cosas del siguiente modo: demos tanto al justo como al injusto el poder de hacer lo que cada uno de ellos quiere, y a continuación sigámoslos para observar hasta dónde lo lleva a cada uno el deseo. Entonces sorprenderemos al justo tomando el mismo camino que el injusto, siguiendo sus propios intereses, lo que toda criatura persigue por naturaleza como un bien, pero que la fuerza de la ley obliga a seguir el camino del respeto por la igualdad.","El poder del que hablo sería efectivo al máximo si aquellos hombres adquirieran una fuerza tal como la que se dice que cierta vez tuvo Giges, el antepasado del lidio. Giges era un pastor que servía al entonces rey de Lidia. Un día sobrevino una gran tormenta y un terremoto que rasgó la tierra y produjo un abismo en el lugar en que Giges llevaba el ganado a pastorear. Asombrado al ver esto, descendió al abismo y halló, entre otras maravillas que narran los mitos, un caballo de bronce, hueco y con ventanillas, a través de las cuales divisó adentro un cadáver de tamaño más grande que el de un hombre, según parecía, y que no tenía nada excepto un anillo de oro en la mano. Giges le quitó el anillo y salió del abismo. Ahora bien, los pastores hacían su reunión habitual para dar al rey el informe mensual concerniente a la hacienda, cuando llegó Giges llevando el anillo. Tras sentarse entre los demás, casualmente volvió el engaste del anillo hacia el interior de su mano. Al suceder esto se tornó invisible para los que estaban sentados allí, quienes se pusieron a hablar de él como si se hubiera ido. Giges se asombró, y luego, examinando el anillo, dio vuelta al engaste hacia afuera y tornó a hacerse visible. Al advertirlo, experimentó con el anillo para ver si tenía tal propiedad, y comprobó que así era: cuando giraba el engaste hacia adentro, su dueño se hacía invisible, y cuando lo giraba hacia afuera, se hacía visible. En cuanto se hubo cerciorado de ello, maquinó el modo de formar parte de los que fueron a la residencia del rey como informantes y, una vez allí, sedujo a la reina y con ayuda de ella mató al rey y se apoderó del reino.","Por consiguiente, si hubiese dos anillos como el de Giges y se diera uno a un hombre justo y otro a uno injusto, ninguno perseveraría en la justicia ni soportaría abstenerse de bienes ajenos, cuando podría tanto apoderarse impunemente de lo que quisiera del mercado, como, al entrar en las casas, acostarse con la mujer que prefiriera, y tanto matar a unos como librar de las cadenas a otros, según su voluntad, y hacer todo como si fuera igual a un dios entre los hombres. En esto, el hombre justo no haría nada diferente del injusto, sino que ambos marcharían por el mismo camino. E incluso se diría que esto es una importante prueba de que nadie es justo si no es forzado a serlo, por no considerarse a la justicia como un bien individual, ya que allí donde cada uno se cree capaz de cometer injusticias, las comete. En efecto, todo hombre piensa que la injusticia le brinda más ventajas individuales que la justicia, y está en lo cierto, si habla de acuerdo con esta teoría."],"source":"Tomado de: Platón IV, D. (1986). República, Traducción y notas de C. Eggers Lan, Madrid, Gredos."}},{"id":"lec-31","question":"¿Cuál de las siguientes afirmaciones constituye una razón a favor de la tesis principal del texto anterior, a saber, que cuando alguien actúa justamente lo hace por obligación y no voluntariamente?","options":["La gente se ve obligada a actuar justamente.","Solo la igualdad garantiza el respeto por la ley.","La injusticia brinda las mismas ventajas individuales que la justicia.","Siempre que una persona cuente con la libertad para cometer injusticias lo hará."],"correct":3,"hint":"Busca la opción que, si fuera cierta, confirmaría que solo somos justos por obligación.","difficulty":"media","timeLimit":180,"explanation":"Competencia que evalúa: reflexiona a partir de un texto y evalúa su contenido.","passage":{"intro":"RESPONDE LAS PREGUNTAS 29 A 33 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","title":"El Anillo de Giges: La Naturaleza de la Justicia","paragraphs":["Nadie es justo por voluntad sino porque no tiene el poder de cometer injusticias. Esto lo percibiremos mejor si nos imaginamos las cosas del siguiente modo: demos tanto al justo como al injusto el poder de hacer lo que cada uno de ellos quiere, y a continuación sigámoslos para observar hasta dónde lo lleva a cada uno el deseo. Entonces sorprenderemos al justo tomando el mismo camino que el injusto, siguiendo sus propios intereses, lo que toda criatura persigue por naturaleza como un bien, pero que la fuerza de la ley obliga a seguir el camino del respeto por la igualdad.","El poder del que hablo sería efectivo al máximo si aquellos hombres adquirieran una fuerza tal como la que se dice que cierta vez tuvo Giges, el antepasado del lidio. Giges era un pastor que servía al entonces rey de Lidia. Un día sobrevino una gran tormenta y un terremoto que rasgó la tierra y produjo un abismo en el lugar en que Giges llevaba el ganado a pastorear. Asombrado al ver esto, descendió al abismo y halló, entre otras maravillas que narran los mitos, un caballo de bronce, hueco y con ventanillas, a través de las cuales divisó adentro un cadáver de tamaño más grande que el de un hombre, según parecía, y que no tenía nada excepto un anillo de oro en la mano. Giges le quitó el anillo y salió del abismo. Ahora bien, los pastores hacían su reunión habitual para dar al rey el informe mensual concerniente a la hacienda, cuando llegó Giges llevando el anillo. Tras sentarse entre los demás, casualmente volvió el engaste del anillo hacia el interior de su mano. Al suceder esto se tornó invisible para los que estaban sentados allí, quienes se pusieron a hablar de él como si se hubiera ido. Giges se asombró, y luego, examinando el anillo, dio vuelta al engaste hacia afuera y tornó a hacerse visible. Al advertirlo, experimentó con el anillo para ver si tenía tal propiedad, y comprobó que así era: cuando giraba el engaste hacia adentro, su dueño se hacía invisible, y cuando lo giraba hacia afuera, se hacía visible. En cuanto se hubo cerciorado de ello, maquinó el modo de formar parte de los que fueron a la residencia del rey como informantes y, una vez allí, sedujo a la reina y con ayuda de ella mató al rey y se apoderó del reino.","Por consiguiente, si hubiese dos anillos como el de Giges y se diera uno a un hombre justo y otro a uno injusto, ninguno perseveraría en la justicia ni soportaría abstenerse de bienes ajenos, cuando podría tanto apoderarse impunemente de lo que quisiera del mercado, como, al entrar en las casas, acostarse con la mujer que prefiriera, y tanto matar a unos como librar de las cadenas a otros, según su voluntad, y hacer todo como si fuera igual a un dios entre los hombres. En esto, el hombre justo no haría nada diferente del injusto, sino que ambos marcharían por el mismo camino. E incluso se diría que esto es una importante prueba de que nadie es justo si no es forzado a serlo, por no considerarse a la justicia como un bien individual, ya que allí donde cada uno se cree capaz de cometer injusticias, las comete. En efecto, todo hombre piensa que la injusticia le brinda más ventajas individuales que la justicia, y está en lo cierto, si habla de acuerdo con esta teoría."],"source":"Tomado de: Platón IV, D. (1986). República, Traducción y notas de C. Eggers Lan, Madrid, Gredos."}},{"id":"lec-32","question":"¿Cuál de las siguientes afirmaciones sintetiza adecuadamente las ideas contenidas en el primer párrafo del texto?","options":["El que alguien sea justo es un deber que se deriva de la conciencia moral que tienen todos los hombres.","El que alguien sea justo resulta de una imposición, pues toda persona sin las restricciones y exigencias de la ley buscará satisfacer sus deseos.","La justicia es una ilusión, ya que lo natural es que una persona busque cumplir sus deseos y alcanzar sus intereses, sin reparar en la igualdad que exige la ley.","La justicia es un ideal inalcanzable, ya que toda persona, por más justa que aparente ser, tiene intereses propios que pueden llevarla a cometer injusticias."],"correct":1,"hint":"El primer párrafo dice que es la ley la que obliga a seguir el camino del respeto.","difficulty":"facil","timeLimit":180,"explanation":"Competencia que evalúa: comprende cómo se articulan las partes de un texto para darle un sentido global.","passage":{"intro":"RESPONDE LAS PREGUNTAS 29 A 33 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","title":"El Anillo de Giges: La Naturaleza de la Justicia","paragraphs":["Nadie es justo por voluntad sino porque no tiene el poder de cometer injusticias. Esto lo percibiremos mejor si nos imaginamos las cosas del siguiente modo: demos tanto al justo como al injusto el poder de hacer lo que cada uno de ellos quiere, y a continuación sigámoslos para observar hasta dónde lo lleva a cada uno el deseo. Entonces sorprenderemos al justo tomando el mismo camino que el injusto, siguiendo sus propios intereses, lo que toda criatura persigue por naturaleza como un bien, pero que la fuerza de la ley obliga a seguir el camino del respeto por la igualdad.","El poder del que hablo sería efectivo al máximo si aquellos hombres adquirieran una fuerza tal como la que se dice que cierta vez tuvo Giges, el antepasado del lidio. Giges era un pastor que servía al entonces rey de Lidia. Un día sobrevino una gran tormenta y un terremoto que rasgó la tierra y produjo un abismo en el lugar en que Giges llevaba el ganado a pastorear. Asombrado al ver esto, descendió al abismo y halló, entre otras maravillas que narran los mitos, un caballo de bronce, hueco y con ventanillas, a través de las cuales divisó adentro un cadáver de tamaño más grande que el de un hombre, según parecía, y que no tenía nada excepto un anillo de oro en la mano. Giges le quitó el anillo y salió del abismo. Ahora bien, los pastores hacían su reunión habitual para dar al rey el informe mensual concerniente a la hacienda, cuando llegó Giges llevando el anillo. Tras sentarse entre los demás, casualmente volvió el engaste del anillo hacia el interior de su mano. Al suceder esto se tornó invisible para los que estaban sentados allí, quienes se pusieron a hablar de él como si se hubiera ido. Giges se asombró, y luego, examinando el anillo, dio vuelta al engaste hacia afuera y tornó a hacerse visible. Al advertirlo, experimentó con el anillo para ver si tenía tal propiedad, y comprobó que así era: cuando giraba el engaste hacia adentro, su dueño se hacía invisible, y cuando lo giraba hacia afuera, se hacía visible. En cuanto se hubo cerciorado de ello, maquinó el modo de formar parte de los que fueron a la residencia del rey como informantes y, una vez allí, sedujo a la reina y con ayuda de ella mató al rey y se apoderó del reino.","Por consiguiente, si hubiese dos anillos como el de Giges y se diera uno a un hombre justo y otro a uno injusto, ninguno perseveraría en la justicia ni soportaría abstenerse de bienes ajenos, cuando podría tanto apoderarse impunemente de lo que quisiera del mercado, como, al entrar en las casas, acostarse con la mujer que prefiriera, y tanto matar a unos como librar de las cadenas a otros, según su voluntad, y hacer todo como si fuera igual a un dios entre los hombres. En esto, el hombre justo no haría nada diferente del injusto, sino que ambos marcharían por el mismo camino. E incluso se diría que esto es una importante prueba de que nadie es justo si no es forzado a serlo, por no considerarse a la justicia como un bien individual, ya que allí donde cada uno se cree capaz de cometer injusticias, las comete. En efecto, todo hombre piensa que la injusticia le brinda más ventajas individuales que la justicia, y está en lo cierto, si habla de acuerdo con esta teoría."],"source":"Tomado de: Platón IV, D. (1986). República, Traducción y notas de C. Eggers Lan, Madrid, Gredos."}},{"id":"lec-33","question":"Dada la estructura del texto anterior, ¿qué propósito general tiene el autor al introducir el relato sobre el anillo de Giges, y cómo lo alcanza?","options":["Promover en la audiencia la idea de que es más ventajoso seguir el camino de la injusticia. El caso de Giges muestra cómo obtuvo beneficios gracias al comportamiento injusto que le posibilitó el anillo.","Convencer a la audiencia de que todo hombre cometerá injusticias cuando tenga la oportunidad. Así lo hizo Giges una vez descubrió el poder que le otorgaba el anillo.","Reforzar en la audiencia la idea de que todos cometemos injusticias. El caso de Giges ilustra cómo las personas aparentemente justas en realidad cometen grandes injusticias.","Persuadir a la audiencia de que actuar justamente requiere mucha fuerza de voluntad. En el caso de Giges, la tentación derivada del poder del anillo doblegó su voluntad."],"correct":1,"hint":"Giges, con poder y sin castigo, actuó injustamente. ¿Qué quiere demostrar el autor con eso?","difficulty":"media","timeLimit":180,"explanation":"Competencia que evalúa: comprende cómo se articulan las partes de un texto para darle un sentido global.","passage":{"intro":"RESPONDE LAS PREGUNTAS 29 A 33 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN","title":"El Anillo de Giges: La Naturaleza de la Justicia","paragraphs":["Nadie es justo por voluntad sino porque no tiene el poder de cometer injusticias. Esto lo percibiremos mejor si nos imaginamos las cosas del siguiente modo: demos tanto al justo como al injusto el poder de hacer lo que cada uno de ellos quiere, y a continuación sigámoslos para observar hasta dónde lo lleva a cada uno el deseo. Entonces sorprenderemos al justo tomando el mismo camino que el injusto, siguiendo sus propios intereses, lo que toda criatura persigue por naturaleza como un bien, pero que la fuerza de la ley obliga a seguir el camino del respeto por la igualdad.","El poder del que hablo sería efectivo al máximo si aquellos hombres adquirieran una fuerza tal como la que se dice que cierta vez tuvo Giges, el antepasado del lidio. Giges era un pastor que servía al entonces rey de Lidia. Un día sobrevino una gran tormenta y un terremoto que rasgó la tierra y produjo un abismo en el lugar en que Giges llevaba el ganado a pastorear. Asombrado al ver esto, descendió al abismo y halló, entre otras maravillas que narran los mitos, un caballo de bronce, hueco y con ventanillas, a través de las cuales divisó adentro un cadáver de tamaño más grande que el de un hombre, según parecía, y que no tenía nada excepto un anillo de oro en la mano. Giges le quitó el anillo y salió del abismo. Ahora bien, los pastores hacían su reunión habitual para dar al rey el informe mensual concerniente a la hacienda, cuando llegó Giges llevando el anillo. Tras sentarse entre los demás, casualmente volvió el engaste del anillo hacia el interior de su mano. Al suceder esto se tornó invisible para los que estaban sentados allí, quienes se pusieron a hablar de él como si se hubiera ido. Giges se asombró, y luego, examinando el anillo, dio vuelta al engaste hacia afuera y tornó a hacerse visible. Al advertirlo, experimentó con el anillo para ver si tenía tal propiedad, y comprobó que así era: cuando giraba el engaste hacia adentro, su dueño se hacía invisible, y cuando lo giraba hacia afuera, se hacía visible. En cuanto se hubo cerciorado de ello, maquinó el modo de formar parte de los que fueron a la residencia del rey como informantes y, una vez allí, sedujo a la reina y con ayuda de ella mató al rey y se apoderó del reino.","Por consiguiente, si hubiese dos anillos como el de Giges y se diera uno a un hombre justo y otro a uno injusto, ninguno perseveraría en la justicia ni soportaría abstenerse de bienes ajenos, cuando podría tanto apoderarse impunemente de lo que quisiera del mercado, como, al entrar en las casas, acostarse con la mujer que prefiriera, y tanto matar a unos como librar de las cadenas a otros, según su voluntad, y hacer todo como si fuera igual a un dios entre los hombres. En esto, el hombre justo no haría nada diferente del injusto, sino que ambos marcharían por el mismo camino. E incluso se diría que esto es una importante prueba de que nadie es justo si no es forzado a serlo, por no considerarse a la justicia como un bien individual, ya que allí donde cada uno se cree capaz de cometer injusticias, las comete. En efecto, todo hombre piensa que la injusticia le brinda más ventajas individuales que la justicia, y está en lo cierto, si habla de acuerdo con esta teoría."],"source":"Tomado de: Platón IV, D. (1986). República, Traducción y notas de C. Eggers Lan, Madrid, Gredos."}}]}$lec2$::jsonb),
    ('biologia', 'Biología', (select coalesce(parent_course_id, id) from public.courses where id = '4d2af3cd-767e-4e14-a364-23fd596ada10'::uuid),
      $bio1${"bank":"biologia","bankRound":1,"passingScore":0,"questions":[{"id":"bio-01","question":"En un ecosistema acuático, se estudia la relación entre la cantidad de oxígeno disuelto en el agua y la supervivencia de una especie de pez. Los investigadores encontraron que cuando la concentración de oxígeno es inferior a 4 mg/L, la mortalidad de los peces aumenta significativamente.\nTeniendo en cuenta esta información, si en un río la concentración de oxígeno disuelto disminuye de 7 mg/L a 2 mg/L debido a un vertimiento de materia orgánica, ¿qué se puede predecir sobre la población de peces?","options":["La población aumentará porque los peces se reproducirán más rápido al haber menos competencia.","La población disminuirá drásticamente porque el bajo nivel de oxígeno afecta su supervivencia.","La población no se verá afectada porque los peces pueden respirar fuera del agua.","La población se mantendrá estable porque el oxígeno disuelto no es importante para los peces."],"correct":1,"hint":"Compara los 2 mg/L con el límite de 4 mg/L que señalan los investigadores.","difficulty":"facil","timeLimit":60,"explanation":"Con 2 mg/L el oxígeno queda muy por debajo del umbral de 4 mg/L a partir del cual aumenta la mortalidad: la población disminuirá."},{"id":"bio-02","question":"Un grupo de estudiantes observó que algunas plantas crecen mejor cuando están cerca de otras plantas de la misma especie. Para explicar este fenómeno, formulan la siguiente hipótesis: \"Las plantas se benefician mutuamente al compartir nutrientes a través de sus raíces\".\nPara poner a prueba esta hipótesis, los estudiantes deberían:","options":["Medir la cantidad de nutrientes en el suelo alrededor de las raíces de una planta solitaria.","Cultivar plantas en dos grupos: uno con raíces que puedan conectarse y otro con raíces separadas por una barrera, y comparar su crecimiento.","Regar todas las plantas con la misma cantidad de agua y medir su crecimiento.","Medir la temperatura del suelo alrededor de las raíces de las plantas."],"correct":1,"hint":"Para poner a prueba una hipótesis necesitas dos grupos que solo se diferencien en lo que quieres probar.","difficulty":"facil","timeLimit":60,"explanation":"Un experimento controlado compara dos grupos que solo difieren en la variable de la hipótesis (raíces conectadas vs. separadas por una barrera). Las otras opciones no ponen a prueba el intercambio de nutrientes."},{"id":"bio-03","question":"En una clase de biología, se estudia el proceso de ósmosis en células vegetales. Se colocan células de una planta en tres soluciones con diferentes concentraciones de sal:\nSolución A: Agua destilada (0% de sal)\nSolución B: Solución con 0.9% de sal (concentración similar al interior de la célula)\nSolución C: Solución con 10% de sal\n¿Qué se espera observar en las células de la planta después de 30 minutos?","options":["En la solución A, las células se encogerán; en la B, permanecerán igual; en la C, se hincharán.","En la solución A, las células se hincharán; en la B, permanecerán igual; en la C, se encogerán.","En las tres soluciones, las células permanecerán igual porque la pared celular las protege.","En la solución A, las células se encogerán; en la B, se hincharán; en la C, permanecerán igual."],"correct":1,"hint":"El agua se mueve hacia donde hay más sal. ¿En qué solución entra agua a la célula y en cuál sale?","difficulty":"media","timeLimit":60,"explanation":"En agua destilada (hipotónica) entra agua y la célula se hincha; al 0,9 % (isotónica) no hay flujo neto; al 10 % (hipertónica) sale agua y la célula se encoge."},{"id":"bio-04","question":"La siguiente tabla muestra el porcentaje de supervivencia de tres especies de bacterias (A, B y C) al ser expuestas a diferentes antibióticos.\nAntibiótico | Bacteria A (%) | Bacteria B (%) | Bacteria C (%)\nAntibiótico X | 10 | 35 | 5\nAntibiótico Y | 45 | 20 | 40\nAntibiótico Z | 5 | 15 | 85\nCon base en la información, ¿cuál de las siguientes afirmaciones es correcta?","options":["La bacteria C es más resistente al antibiótico Z que a los otros antibióticos.","La bacteria A es la más sensible a todos los antibióticos.","El antibiótico X es igual de efectivo contra las tres bacterias.","La bacteria B es la más resistente al antibiótico Y."],"correct":0,"hint":"En la tabla, sobrevivir mucho significa ser resistente: busca el porcentaje más alto.","difficulty":"facil","timeLimit":60,"explanation":"La bacteria C sobrevive un 85 % con el antibiótico Z, frente a 5 % con X y 40 % con Y: es su mayor resistencia."},{"id":"bio-05","question":"En la naturaleza, algunas especies de orquídeas han desarrollado flores con formas y colores que imitan a insectos hembra. Esto atrae a los insectos macho, quienes intentan aparearse con la flor y, al hacerlo, transportan el polen a otras flores.\nEste fenómeno es un ejemplo de:","options":["Mimetismo engañoso, porque la orquídea se beneficia y el insecto es engañado sin recibir nada a cambio.","Mutualismo, porque ambas especies se benefician.","Parasitismo, porque la orquídea se alimenta del insecto.","Competencia, porque ambas especies compiten por el mismo recurso."],"correct":0,"hint":"Pregúntate quién gana en esta relación: ¿la orquídea, el insecto o los dos? ¿Alguien se come a alguien?","difficulty":"media","timeLimit":60,"explanation":"La orquídea imita a la hembra del insecto y así consigue que el macho la polinice, pero el insecto no recibe nada a cambio (ni néctar ni pareja): es un mimetismo engañoso. No es mutualismo, porque solo una especie se beneficia; tampoco parasitismo, porque la orquídea no se alimenta del insecto, ni competencia, porque no se disputan ningún recurso."},{"id":"bio-06","question":"Un estudiante tiene una planta en su casa que no crece adecuadamente. Investiga y encuentra que la planta necesita luz solar directa para realizar la fotosíntesis. Decide colocar la planta cerca de una ventana, pero nota que la luz solo llega por la mañana.\n¿Qué debe hacer el estudiante para que la planta realice la fotosíntesis de manera más eficiente?","options":["Regar la planta con más agua para compensar la falta de luz.","Abonar la planta con fertilizantes ricos en nitrógeno.","Colocar la planta en un lugar donde reciba luz solar durante más horas al día.","Podar las hojas secas para que la planta crezca más rápido."],"correct":2,"hint":"Ni el agua ni el abono reemplazan lo que impulsa la fotosíntesis.","difficulty":"facil","timeLimit":60,"explanation":"La fotosíntesis depende de la luz: más horas de luz solar directa permiten más fotosíntesis. Ni el agua ni el abono reemplazan la luz."},{"id":"bio-07","question":"El siguiente modelo muestra una cadena alimentaria en un ecosistema terrestre:\nHierba → Saltamontes → Rana → Serpiente → Águila\nSi el número de serpientes disminuye drásticamente debido a una enfermedad, ¿cuál de las siguientes afirmaciones describe mejor lo que sucederá en este ecosistema?","options":["La población de águilas aumentará porque tendrán más alimento disponible.","La población de ranas disminuirá porque serán más cazadas por las serpientes.","La población de ranas aumentará porque su depredador (la serpiente) disminuyó.","La población de saltamontes disminuirá porque las ranas se comerán más hierba."],"correct":2,"hint":"Si disminuye un depredador, ¿qué le pasa a la presa que se comía?","difficulty":"dificil","timeLimit":60,"explanation":"Las serpientes se comen a las ranas: si las serpientes disminuyen, las ranas tienen menos depredadores y su población aumenta."},{"id":"bio-08","question":"Se realiza un experimento en el que se cultivan dos grupos de la misma especie de planta. El grupo 1 se cultiva en suelo con bacterias fijadoras de nitrógeno, mientras que el grupo 2 se cultiva en suelo estéril (sin bacterias). Ambos grupos reciben la misma cantidad de agua, luz y nutrientes.\nDespués de 4 semanas, se observa que el grupo 1 tiene un crecimiento significativamente mayor que el grupo 2.\n¿Qué conclusión es más adecuada a partir de estos resultados?","options":["Las bacterias fijadoras de nitrógeno compiten con las plantas por los nutrientes.","Las bacterias fijadoras de nitrógeno benefician el crecimiento de las plantas.","Las plantas crecen mejor en suelo estéril porque no hay competencia.","Las bacterias fijadoras de nitrógeno no tienen ningún efecto sobre las plantas."],"correct":1,"hint":"Lo único que cambió entre los dos grupos fue la presencia de las bacterias.","difficulty":"media","timeLimit":60,"explanation":"El único factor distinto fue la presencia de bacterias fijadoras de nitrógeno, que aportan nitrógeno aprovechable: benefician el crecimiento."},{"id":"bio-09","question":"En la reproducción de una especie de flor, el color de los pétalos está determinado por un gen con dos alelos: el alelo R (rojo) es dominante y el alelo r (blanco) es recesivo.\nSi se cruzan dos plantas heterocigotas (Rr), ¿cuál es la probabilidad de que una planta descendiente tenga flores blancas?","options":["25%","50%","75%","100%"],"correct":0,"hint":"Haz el cuadro de Punnett Rr × Rr: ¿cuántas de las 4 casillas son rr?","difficulty":"dificil","timeLimit":60,"explanation":"Rr × Rr da RR, Rr, Rr y rr: solo 1 de 4 (25 %) es rr y tiene flores blancas."},{"id":"bio-10","question":"La siguiente gráfica muestra la cantidad de glucosa en la sangre de una persona después de consumir una comida rica en carbohidratos.\nSegún la información de la gráfica, ¿qué proceso ocurre entre los 60 y los 120 minutos para que el nivel de glucosa comience a disminuir?","options":["La glucosa se convierte en glucógeno por acción de la insulina.","La glucosa se elimina a través de la orina.","La glucosa se convierte en proteínas por acción de las enzimas digestivas.","La glucosa se almacena en los pulmones para ser utilizada en la respiración."],"correct":0,"hint":"¿Qué hormona baja la glucosa en la sangre y en qué forma la guarda el cuerpo?","difficulty":"media","timeLimit":75,"image":"/preguntas/ciencias/glucosa-en-sangre.jpg","explanation":"Tras el pico, la insulina hace que el hígado y los músculos conviertan la glucosa en glucógeno, y el nivel en sangre baja."}]}$bio1$::jsonb,
      $bio2${"bank":"biologia","bankRound":2,"passingScore":0,"questions":[{"id":"bio-11","question":"Un equipo de limnólogos investiga un lago afectado por vertimientos agrícolas de fosfatos. Durante un año midieron la concentración de fosfato, la biomasa de fitoplancton, la penetración de luz solar y la concentración de oxígeno disuelto en el fondo del cuerpo de agua. Los resultados mostraron que a concentraciones de fosfato >0.1 mg/L, la biomasa de fitoplancton se multiplicó por diez, la penetración de la luz cayó al mínimo y el oxígeno disuelto en el fondo llegó a 0 mg/L (anoxia), provocando mortandad masiva de peces bénticos.\n¿Cuál de los siguientes esquemas de causalidad explica correctamente la secuencia de eventos observada?","options":["Incremento de fosfatos → Eutrofización → Proliferación masiva de fitoplancton → Reducción de la penetración de luz → Muerte y descomposición bacteriana aerobia del fitoplancton → Anoxia profunda.","Incremento de fosfatos → Toxicidad directa en peces → Disminución de depredadores → Proliferación de fitoplancton → Bloqueo de la luz por residuos orgánicos.","Incremento de fosfatos → Reducción del oxígeno por consumo de fotosíntesis nocturna → Muerte de peces → Eutrofización → Bloqueo de luz.","Incremento de fosfatos → Aumento de la penetración de luz → Sobrecalentamiento del agua → Pérdida de solubilidad de oxígeno → Muerte masiva de peces."],"correct":0,"hint":"Sigue la cadena: más nutrientes → más algas → menos luz → ¿quién gasta el oxígeno al descomponerlas?","difficulty":"dificil","timeLimit":90,"explanation":"La eutrofización genera florecimiento algal que bloquea luz y descompone materia oxigenada."},{"id":"bio-12","question":"En una población de polillas de una especie forestal, la coloración de las alas depende de un solo gen con un alelo dominante A (gris oscuro) y un alelo recesivo a (gris claro). Debido a un evento de contaminación industrial por hollín, la corteza de los árboles se oscureció. Tras 20 generaciones, la frecuencia del fenotipo claro pasó de 0.81 a 0.09. Suponga que la población se encuentra en equilibrio tras el cese de la selección en la generación 20.\n¿Cuál fue el cambio en la frecuencia del alelo a en esta población debido a la presión de selección ambiental?","options":["Pasó de 0.9 a 0.3.","Pasó de 0.81 a 0.09.","Pasó de 0.9 a 0.09.","Pasó de 0.45 a 0.15."],"correct":0,"hint":"En Hardy-Weinberg, el fenotipo recesivo es q². Saca la raíz cuadrada en cada momento.","difficulty":"dificil","timeLimit":90,"explanation":"q1 = sqrt(0.81) = 0.9; q2 = sqrt(0.09) = 0.3."},{"id":"bio-13","question":"Un investigador trata un cultivo de células epiteliales con Oligomicina, un inhibidor de la ATP sintasa mitocondrial. Posteriormente, coloca las células en un medio hipotónico con una alta concentración de glucosa y baja concentración de sodio (Na⁺). Observa que el transporte activo secundario de glucosa acoplado al gradiente de sodio hacia el interior de la célula disminuye drásticamente hasta detenerse.\n¿Por qué la inhibición de la ATP sintasa afecta un transporte que no consume ATP directamente?","options":["La glucosa requiere ATP para atravesar la membrana bilipídica directamente.","La bomba Na⁺/K⁺ ATPasa deja de funcionar por falta de ATP, perdiendo el gradiente electroquímico de sodio que impulsa el simporte.","La oligomicina bloquea la proteína de canal por donde ingresa la glucosa por difusión facilitada.","La falta de ATP altera la fluidez lipídica imposibilitando la endocitosis del complejo Na⁺/glucosa."],"correct":1,"hint":"El transporte secundario usa un gradiente que otra bomba mantiene gastando ATP.","difficulty":"dificil","timeLimit":90,"explanation":"Sin ATP, la bomba Na+/K+ falla y se destruye el gradiente necesario para el simporte."},{"id":"bio-14","question":"La siguiente secuencia corresponde a un fragmento de la hebra molde de ADN de un gen procariótico:\n3' - TAC - GGG - TTT - CTA - ACT - 5'\nOcurre una mutación por sustitución en la tercera base del segundo codón, cambiando la hebra molde a:\n3' - TAC - GGA - TTT - CTA - ACT - 5'\nSabiendo que en el código genético tanto el codón CCU como CCC codifican para el aminoácido Prolina (Pro):","options":["Se producirá una proteína trunca porque se genera un codón de parada prematuro.","Ocurrirá una mutación de cambio de pauta de lectura (frameshift) alterando toda la proteína.","La secuencia de aminoácidos sintetizada no sufrirá cambios (mutación silenciosa).","La ARN polimerasa no podrá reconocer el sitio promotor para iniciar la transcripción."],"correct":2,"hint":"Pasa la hebra molde a ARNm y mira qué aminoácido codifica el codón que cambió.","difficulty":"media","timeLimit":90,"explanation":"Mutación silenciosa: ambos codones sintetizan Prolina."},{"id":"bio-15","question":"Durante un ejercicio de alta intensidad sostenido en un clima cálido y seco, un atleta sufre una deshidratación severa. Sus niveles plasmáticos de osmolaridad aumentan significativamente.\n¿Qué respuesta endocrina y fisiológica integrada se desencadena para restablecer la homeostasis hídrica?","options":["Inhibición de la Hormona Antidiurética (ADH) y disminución de la reabsorción de agua en los túbulos colectores renales.","Liberación de ADH por la neurohipófisis y aumento de aquaporinas en los túbulos colectores renales para aumentar la reabsorción de agua.","Secreción de péptido natriurético auricular (ANP) para favorecer la excreción masiva de sodio y agua por la orina.","Inhibición de la secreción de aldosterona para retener mayor volumen de agua orina sin retener sales."],"correct":1,"hint":"Con el cuerpo deshidratado, los riñones deben ahorrar agua: ¿qué hormona da esa orden?","difficulty":"facil","timeLimit":90,"explanation":"La ADH aumenta las acuaporinas en túbulos renales para retener agua."},{"id":"bio-16","question":"Se realiza un experimento cortando la banda de Caspary en la endodermis de las raíces de una planta experimental mediante microcirugía. A continuación, se riega la planta con una solución que contiene un colorante rojo no liposoluble de peso molecular elevado y iones tóxicos de aluminio (Al³⁺).\n¿Qué se observará en el sistema vascular (xilema) de esta planta?","options":["El colorante y los iones Al³⁺ ingresarán libremente al xilema a través de la vía apoplástica sin control selectivo.","La planta bombeará los iones Al³⁺ fuera del tallo utilizando la vía simplástica mediante transporte activo.","Se detendrá por completo la absorción de agua debido al colapso de la presión radicular por osmosis.","Aumentará la fotosíntesis debido al rápido transporte apoplástico hacia el mesófilo."],"correct":0,"hint":"La banda de Caspary es el filtro que obliga al agua a pasar por dentro de las células. ¿Y si se rompe?","difficulty":"dificil","timeLimit":90,"explanation":"Romper la banda de Caspary elimina el filtro apoplástico selectivo."},{"id":"bio-17","question":"Se trata un cultivo de células tumorales en fase G1 con un fármaco experimental que inhibe permanentemente la fosforilación de la proteína del retinoblastoma (Rb) por parte del complejo Ciclina D-CDK4.\n¿Cuál es el efecto directo de este fármaco sobre la progresión del ciclo celular?","options":["Las células quedarán arrestadas en la fase G1, impidiendo la transición a la fase S.","Las células duplicarán su ADN indefinidamente sin dividirse.","Se acelerará la mitosis al no haber puntos de control activos.","La célula iniciará apoptosis inmediata únicamente durante la anafase."],"correct":0,"hint":"La proteína Rb sin fosforilar mantiene frenado el paso de G1 a S.","difficulty":"media","timeLimit":90,"explanation":"Rb inactivo retiene el factor E2F bloqueando el avance a fase S."},{"id":"bio-18","question":"Un paciente es expuesto por primera vez al antígeno X y desarrolla una respuesta inmune primaria tardía y moderada. Tres semanas después es expuesto simultáneamente al antígeno X y a un nuevo antígeno Y.\n¿Cómo será la respuesta de anticuerpos (IgG) frente a los antígenos X e Y?","options":["La respuesta frente a X e Y será idéntica en tiempo y magnitud por ser una respuesta inespecífica.","La respuesta frente a X será rápida y de gran magnitud (secundaria), mientras que la de Y será lenta y moderada (primaria).","La presencia de Y inhibirá la respuesta de memoria contra X debido a la competencia por receptores.","Los anticuerpos generados contra X neutralizarán al antígeno Y por inmunidad cruzada obligatoria."],"correct":1,"hint":"El sistema inmune tiene memoria para lo que ya conoce, no para lo nuevo.","difficulty":"media","timeLimit":90,"explanation":"Las células de memoria provocan respuesta secundaria acelerada para X."},{"id":"bio-19","question":"En un ecosistema marino contaminado por metilmercurio (sustancia liposoluble y persistente), se analiza la concentración de esta toxina por gramo de tejido en cuatro organismos:\nOrganismo 1: Fitoplancton\nOrganismo 2: Sardinas (Consumidor primario)\nOrganismo 3: Atún (Consumidor secundario/terciario)\nOrganismo 4: Tiburón blanco (Superdepredador)\n¿En cuál organismo se registrará la mayor concentración de metilmercurio y cuál es el fenómeno ecológico responsable?","options":["Organismo 1, por estar en contacto directo con la fuente de contaminación en la columna de agua.","Organismo 2, por presentar la tasa metabólica más alta de ingestión de alimento.","Organismo 4, debido al proceso de biomagnificación a lo largo de la cadena trófica.","Organismo 3, ya que el fitoplancton degrada el mercurio antes de transferirlo."],"correct":2,"hint":"Una sustancia persistente se va acumulando en cada eslabón de la cadena trófica.","difficulty":"media","timeLimit":90,"explanation":"Biomagnificación en el superdepredador por sustancia persistente."},{"id":"bio-20","question":"Los virus de ARN de cadena negativa, como el virus de la rabia, deben llevar empaquetada dentro de su cápside una enzima específica para poder iniciar la replicación dentro de la célula hospedadora.\n¿Cuál es esta enzima y por qué es indispensable que venga dentro del virión?","options":["ADN polimerasa dependiente de ADN; porque la célula carece de mecanismos de transcripción.","ARN polimerasa dependiente de ARN; porque las células eucariotas no poseen enzimas nativas para sintetizar ARN a partir de un molde de ARN.","Transcriptasa inversa; para integrar el genoma vírico al ADN genómico del huésped en el núcleo.","ARN ligasa; para reparar los fragmentos cortados por los ribosomas citoplasmáticos."],"correct":1,"hint":"La célula sabe copiar ADN y pasar ADN a ARN, pero no fabricar ARN a partir de ARN.","difficulty":"media","timeLimit":90,"explanation":"Las células no poseen ARN polimerasa dependiente de ARN nativa."}]}$bio2$::jsonb),
    ('fisica', 'Física', (select id from public.courses where parent_course_id is null and name like '%Ciencias Naturales — Física' order by created_at limit 1),
      $fis1${"bank":"fisica","bankRound":1,"passingScore":0,"questions":[{"id":"fis-01","question":"Un automóvil se mueve a una velocidad constante de 20 m/s durante 10 segundos. ¿Qué distancia recorre el automóvil en este tiempo?","options":["2 metros","20 metros","100 metros","200 metros"],"correct":3,"hint":"Velocidad constante: distancia = velocidad × tiempo.","difficulty":"dificil","timeLimit":60,"explanation":"d = v·t = 20 m/s × 10 s = 200 m."},{"id":"fis-02","question":"Dos cargas eléctricas puntuales, cada una de +2 μC, se encuentran separadas por una distancia de 0.3 metros en el vacío. La constante de Coulomb es k = 9 × 10⁹ N·m²/C².\n¿Cuál es la fuerza entre ellas?","options":["0.04 N (repulsiva)","0.04 N (atractiva)","0.4 N (repulsiva)","0.4 N (atractiva)"],"correct":2,"hint":"F = k·q₁·q₂ / r². Y ojo: ¿cargas del mismo signo se atraen o se repelen?","difficulty":"media","timeLimit":60,"explanation":"F = 9×10⁹ × (2×10⁻⁶)² / 0,3² = 0,036 / 0,09 = 0,4 N. Las cargas del mismo signo se repelen."},{"id":"fis-03","question":"Un ladrillo de 2 kg se encuentra en reposo sobre una mesa. La aceleración de la gravedad es g = 10 m/s².\n¿Cuál es el peso del ladrillo?","options":["2 N","5 N","10 N","20 N"],"correct":3,"hint":"Peso = masa × gravedad.","difficulty":"facil","timeLimit":60,"explanation":"P = m·g = 2 kg × 10 m/s² = 20 N."},{"id":"fis-04","question":"Un rayo de luz pasa del aire al agua. Se observa que el rayo cambia de dirección al entrar al agua.\n¿Cómo se llama este fenómeno?","options":["Reflexión","Refracción","Difracción","Dispersión"],"correct":1,"hint":"La luz cambia de medio, y con él cambian su velocidad y su dirección.","difficulty":"dificil","timeLimit":60,"explanation":"La refracción es el cambio de dirección de la luz al pasar de un medio a otro con distinta velocidad de propagación."},{"id":"fis-05","question":"Una fuerza de 50 N se aplica para mover un bloque una distancia de 2 metros.\nSi se aplica la misma fuerza pero en dirección contraria al movimiento, ¿qué sucede con el trabajo realizado?","options":["El trabajo es positivo.","El trabajo es negativo.","El trabajo es cero.","El trabajo se duplica."],"correct":1,"hint":"Si la fuerza va en contra del desplazamiento, el ángulo entre ellos es 180°.","difficulty":"dificil","timeLimit":60,"explanation":"W = F·d·cos θ. Con la fuerza opuesta al movimiento, θ = 180° y cos 180° = −1: el trabajo es negativo."},{"id":"fis-06","question":"Un patinador sobre hielo extiende sus brazos mientras gira, y su velocidad angular disminuye. Cuando acerca sus brazos al cuerpo, su velocidad angular aumenta.\n¿Qué principio físico explica este comportamiento?","options":["Principio de Arquímedes","Principio de Pascal","Conservación del momento angular","Ley de Hooke"],"correct":2,"hint":"Al recoger los brazos, el patinador reduce su momento de inercia… algo tiene que conservarse.","difficulty":"media","timeLimit":60,"explanation":"Sin torques externos, L = I·ω se conserva: al reducir I (brazos recogidos), ω aumenta."},{"id":"fis-07","question":"Un objeto se lanza hacia arriba con una velocidad inicial de 30 m/s. La aceleración de la gravedad es g = 10 m/s².\n¿Cuánto tiempo tarda en alcanzar su altura máxima?","options":["1.5 s","3 s","6 s","10 s"],"correct":1,"hint":"En la altura máxima la velocidad es 0: ¿cuánto tarda la gravedad en frenar 30 m/s?","difficulty":"media","timeLimit":60,"explanation":"v = v₀ − g·t → 0 = 30 − 10·t → t = 3 s."},{"id":"fis-08","question":"Un circuito eléctrico tiene una resistencia de 10 Ω y una diferencia de potencial de 120 V.\n¿Cuál es la corriente que circula por el circuito?","options":["0.083 A","1.2 A","12 A","120 A"],"correct":2,"hint":"Ley de Ohm: I = V / R.","difficulty":"media","timeLimit":60,"explanation":"I = V / R = 120 V / 10 Ω = 12 A."},{"id":"fis-09","question":"Una onda se propaga en una cuerda con una frecuencia de 5 Hz y una longitud de onda de 0.4 metros.\n¿Cuál es la velocidad de propagación de la onda?","options":["0.08 m/s","1.25 m/s","2 m/s","12.5 m/s"],"correct":2,"hint":"Velocidad de una onda = frecuencia × longitud de onda.","difficulty":"facil","timeLimit":60,"explanation":"v = f·λ = 5 Hz × 0,4 m = 2 m/s."},{"id":"fis-10","question":"La siguiente gráfica muestra la relación entre la fuerza aplicada y el alargamiento de un resorte.\nSegún la gráfica, ¿qué ley física describe esta relación?","options":["Ley de Newton","Ley de Hooke","Ley de Coulomb","Ley de Ohm"],"correct":1,"hint":"La gráfica es una recta que pasa por el origen: la fuerza es proporcional al alargamiento.","difficulty":"dificil","timeLimit":75,"image":"/preguntas/ciencias/ley-de-hooke.jpg","explanation":"La fuerza es proporcional al alargamiento (F = k·x): es la ley de Hooke. Aquí k = 50 N/m."}]}$fis1$::jsonb,
      $fis2${"bank":"fisica","bankRound":2,"passingScore":0,"questions":[{"id":"fis-11","question":"Un proyectil es lanzado con un ángulo de elevación θ=30° respecto a la horizontal desde el suelo con una velocidad inicial de 40 m/s. Desprecie la resistencia del aire y asuma g=10 m/s². (sin30°=0.5, cos30°=0.866).\n¿Cuál es la altura máxima alcanzada por el proyectil y cuál es su velocidad en el punto más alto de la trayectoria?","options":["Altura máxima =20 m; Velocidad en el ápex =34.64 m/s.","Altura máxima =40 m; Velocidad en el ápex =0 m/s.","Altura máxima =20 m; Velocidad en el ápex =0 m/s.","Altura máxima =80 m; Velocidad en el ápex =20 m/s."],"correct":0,"hint":"Separa la velocidad en componentes: la vertical se anula en la cima; la horizontal no cambia.","difficulty":"facil","timeLimit":90,"explanation":"vy0 = 20 m/s -> hmax = 20 m. En el ápex vy=0 y vx = 34.64 m/s."},{"id":"fis-12","question":"Dos bloques de masas m₁=3 kg y m₂=2 kg están conectados por una cuerda inextensible y de masa despreciable que pasa por una polea sin fricción. El bloque m₁ descansa sobre una superficie horizontal con un coeficiente de fricción cinético μ_k=0.2, mientras que m₂ cuelga libremente de forma vertical. Asuma g=10 m/s².\n¿Cuál es la aceleración del sistema al liberarse desde el reposo?","options":["2.8 m/s²","4.0 m/s²","1.4 m/s²","5.0 m/s²"],"correct":0,"hint":"Lo que mueve el sistema es el peso de m₂; lo que lo frena es la fricción sobre m₁. Las dos masas se aceleran juntas.","difficulty":"facil","timeLimit":105,"image":"/preguntas/ciencias/bloques-polea.jpg","explanation":"a = (m2*g - mu*m1*g)/(m1+m2) = (20 - 6)/5 = 2.8 m/s^2."},{"id":"fis-13","question":"Un objeto de 1 kg de masa se suelta desde el reposo desde una altura H=5 m sobre una rampa curva sin fricción. En la base de la rampa colisiona e impacta frontalmente contra un resorte ideal de constante elástica k=1000 N/m. (g=10 m/s²).\n¿Cuál es la compresión máxima (x) que experimenta el resorte?","options":["0.1 m","0.316 m","0.5 m","1.0 m"],"correct":1,"hint":"Toda la energía potencial del inicio termina como energía elástica: mgh = ½kx².","difficulty":"facil","timeLimit":105,"image":"/preguntas/ciencias/rampa-resorte.jpg","explanation":"mgh = 0.5*k*x^2 -> 50 = 500 x^2 -> x = sqrt(0.1) = 0.316 m."},{"id":"fis-14","question":"Un tanque cilíndrico abierto a la atmósfera contiene agua de densidad ρ=1000 kg/m³ hasta una altura h₁=4.5 m. A una profundidad de h₂=3.2 m por debajo de la superficie libre del agua se perfora un pequeño orificio en el lateral del tanque. Asuma g=10 m/s².\n¿Cuál es la velocidad de salida (v) del agua a través del orificio en el instante inicial?","options":["v=8.0 m/s","v=9.48 m/s","v=64.0 m/s","v=3.0 m/s"],"correct":0,"hint":"Torricelli: v = √(2gh), con h medida desde la superficie hasta el orificio.","difficulty":"dificil","timeLimit":90,"explanation":"Torricelli: v = sqrt(2*g*h) = sqrt(2*10*3.2) = 8 m/s."},{"id":"fis-15","question":"Dado el siguiente circuito eléctrico alimentado por una fuente ideal de voltaje de V=12 V:\nUna resistencia R₁=4 Ω está conectada en serie con una combinación en paralelo de dos resistencias identicas R₂=6 Ω y R₃=6 Ω.\n¿Cuál es la corriente total suministrada por la fuente y la potencia disipada por la resistencia R₁?","options":["I_total=1.71 A; P₁=11.7 W.","I_total=1.0 A; P₁=4.0 W.","I_total=1.71 A; P₁=23.4 W.","I_total=0.75 A; P₁=2.25 W."],"correct":0,"hint":"Primero resuelve las dos de 6 Ω en paralelo; después súmales la de 4 Ω en serie.","difficulty":"dificil","timeLimit":105,"image":"/preguntas/ciencias/circuito-mixto.jpg","explanation":"Req = 4 + 3 = 7 Ω; I = 12/7 = 1.71 A; P1 = I^2*R1 = 11.7 W."},{"id":"fis-16","question":"Una ambulancia se desplaza por una avenida recta a una velocidad constante de v_s=34 m/s y emite una sirena con una frecuencia propia de f₀=700 Hz. Un peatón inmóvil se encuentra en la acera. Sabiendo que la velocidad del sonido en el aire es v=340 m/s:\n¿Cuál es la frecuencia percibida por el peatón mientras la ambulancia se aproxima hacia él y cuando se aleja, respectivamente?","options":["Se aproxima: 777.7 Hz; Se aleja: 636.3 Hz.","Se aproxima: 636.3 Hz; Se aleja: 777.7 Hz.","Se aproxima: 700.0 Hz; Se aleja: 700.0 Hz.","Se aproxima: 840.0 Hz; Se aleja: 560.0 Hz."],"correct":0,"hint":"Cuando la fuente se acerca el sonido se oye más agudo; cuando se aleja, más grave.","difficulty":"dificil","timeLimit":90,"explanation":"f_aprox = 700*(340/306) = 777.7 Hz; f_aleja = 700*(340/374) = 636.3 Hz."},{"id":"fis-17","question":"Un motor térmico opera siguiendo un ciclo de Carnot entre dos reservorios térmicos a temperaturas T_H=600 K (foco caliente) y T_C=300 K (foco frío). En cada ciclo, el motor absorbe 1200 J de calor desde el reservorio caliente.\n¿Cuál es la eficiencia máxima teórica del motor y la cantidad de trabajo neto producido por ciclo?","options":["Eficiencia =50%; Trabajo =600 J.","Eficiencia =25%; Trabajo =300 J.","Eficiencia =75%; Trabajo =900 J.","Eficiencia =100%; Trabajo =1200 J."],"correct":0,"hint":"Eficiencia de Carnot = 1 − T fría / T caliente.","difficulty":"facil","timeLimit":90,"explanation":"η = 1 - 300/600 = 0.5 (50%); W = 0.5 * 1200 = 600 J."},{"id":"fis-18","question":"Se coloca un objeto de 5 cm de altura a una distancia de 15 cm frente a un espejo cóncavo cuyo radio de curvatura es R=20 cm (distancia focal f=10 cm).\n¿A qué distancia del espejo (q) se forma la imagen y cuál es su naturaleza?","options":["q=+30 cm; Imagen real, invertida y de mayor tamaño.","q=-30 cm; Imagen virtual, derecha y de menor tamaño.","q=+6 cm; Imagen real, derecha y reducida.","q=+10 cm; Imagen real, invertida de igual tamaño."],"correct":0,"hint":"Ecuación del espejo: 1/f = 1/dₒ + 1/dᵢ. El objeto está entre f y 2f.","difficulty":"dificil","timeLimit":90,"explanation":"1/10 = 1/15 + 1/q -> q = +30 cm (Real e invertida)."},{"id":"fis-19","question":"Se ilumina una placa metálica con radiación monocromática cuya energía de fotón es E_fotón=4.5 eV. La función de trabajo (función umbral) de dicho metal es Φ=2.1 eV.\n¿Cuál es la energía cinética máxima (E_k,máx) de los fotoelectrones emitidos?","options":["E_k,máx=6.6 eV","E_k,máx=2.4 eV","E_k,máx=2.1 eV","No se emiten electrones porque la energía del fotón es superior al trabajo de extracción."],"correct":1,"hint":"La energía del fotón se reparte: una parte arranca el electrón y el resto es energía cinética.","difficulty":"dificil","timeLimit":90,"explanation":"Ek = hν - W = 4.5 - 2.1 = 2.4 eV."},{"id":"fis-20","question":"Dos satélites artificiales A y B orbitan alrededor de la Tierra en órbitas circulares. La distancia orbital del satélite B desde el centro de la Tierra es el cuádruple de la distancia orbital del satélite A (R_B=4R_A).\nSegún la tercera ley de Kepler, ¿cómo se relaciona el periodo orbital del satélite B (T_B) con el del satélite A (T_A)?","options":["T_B=2T_A","T_B=4T_A","T_B=8T_A","T_B=16T_A"],"correct":2,"hint":"Tercera ley de Kepler: T² es proporcional a R³.","difficulty":"media","timeLimit":90,"explanation":"T^2 es proporcional a R^3 -> (4)^1.5 = 8. TB = 8 TA."}]}$fis2$::jsonb),
    ('quimica', 'Química', (select id from public.courses where parent_course_id is null and name like '%Ciencias Naturales — Química' order by created_at limit 1),
      $qui1${"bank":"quimica","bankRound":1,"passingScore":0,"questions":[{"id":"qui-01","question":"Un estudiante quiere clasificar dos sustancias. Para ello, realiza las siguientes observaciones:\nSustancia 1: Es un líquido transparente. Al calentarlo, hierve a 100°C y todo el líquido se evapora sin dejar residuo.\nSustancia 2: Es un líquido transparente. Al calentarlo, hierve a un rango de temperatura entre 78°C y 100°C, y deja un residuo sólido después de la evaporación.\nSegún estas observaciones, ¿cómo se clasifican las sustancias 1 y 2?","options":["La sustancia 1 es un compuesto puro y la sustancia 2 es una mezcla.","La sustancia 1 es una mezcla y la sustancia 2 es un compuesto puro.","Ambas sustancias son compuestos puros.","Ambas sustancias son mezclas."],"correct":0,"hint":"Una sustancia pura hierve a una temperatura fija y no deja residuo.","difficulty":"facil","timeLimit":60,"explanation":"La sustancia 1 hierve a una temperatura fija y no deja residuo: es pura. La 2 hierve en un rango y deja residuo: es una mezcla."},{"id":"qui-02","question":"En una reacción química, se combinan 10 gramos de sustancia A con 10 gramos de sustancia B. Después de la reacción, se obtienen 15 gramos de un producto C y se observa que queda un residuo de 5 gramos de la sustancia B sin reaccionar.\n¿Qué principio explica esta observación?","options":["La ley de las proporciones definidas.","La ley de la conservación de la masa.","La ley de las proporciones múltiples.","La ley de los gases ideales."],"correct":1,"hint":"Suma la masa de lo que entró y compárala con la de lo que salió (producto + sobrante).","difficulty":"media","timeLimit":60,"explanation":"Entran 20 g (10 + 10) y salen 20 g (15 g de C + 5 g de B sin reaccionar): la masa se conserva."},{"id":"qui-03","question":"El ácido clorhídrico (HCl) reacciona con el hidróxido de sodio (NaOH) para formar cloruro de sodio (NaCl) y agua (H₂O), según la siguiente ecuación:\nHCl + NaOH → NaCl + H₂O\nSi se hacen reaccionar 36.5 g de HCl con 40 g de NaOH, y se obtienen 58.5 g de NaCl, ¿cuánta agua se produce?","options":["18 g","20 g","36 g","40 g"],"correct":0,"hint":"La masa de los reactivos es igual a la de los productos: resta.","difficulty":"media","timeLimit":60,"explanation":"Por conservación de la masa: 36,5 + 40 = 76,5 g de reactivos; 76,5 − 58,5 = 18 g de agua."},{"id":"qui-04","question":"Se tiene una solución de ácido sulfúrico (H₂SO₄) al 25% en masa. Esto significa que en 100 gramos de solución hay 25 gramos de H₂SO₄ y 75 gramos de agua.\nSi se desea preparar 500 gramos de esta solución, ¿cuántos gramos de H₂SO₄ se necesitan?","options":["25 gramos","50 gramos","100 gramos","125 gramos"],"correct":3,"hint":"Si 100 g de solución tienen 25 g de ácido, ¿cuánto tendrán 500 g?","difficulty":"media","timeLimit":60,"explanation":"25 g por cada 100 g de solución: en 500 g hay 5 × 25 = 125 g de H₂SO₄."},{"id":"qui-05","question":"La siguiente gráfica muestra la solubilidad de tres sales (X, Y y Z) en agua a diferentes temperaturas.\nSegún la gráfica, ¿cuál de las siguientes afirmaciones es correcta?","options":["La sal Y es la más soluble a todas las temperaturas.","La sal Z aumenta su solubilidad al aumentar la temperatura.","La sal X es más soluble a 80°C que a 20°C.","La sal Y es menos soluble a 60°C que a 20°C."],"correct":2,"hint":"Ubica en la gráfica la línea de cada sal a 20 °C y a 80 °C y compara.","difficulty":"media","timeLimit":75,"image":"/preguntas/ciencias/solubilidad-sales.jpg","explanation":"La línea de la sal X sube de unos 33 g a 20 °C a unos 42 g a 80 °C: es más soluble a 80 °C."},{"id":"qui-06","question":"El siguiente modelo representa la estructura atómica de un elemento:\nNúcleo: contiene 11 protones y 12 neutrones.\nNube electrónica: contiene 11 electrones.\n¿Cuál es el número de masa de este elemento?","options":["11","12","23","33"],"correct":2,"hint":"El número de masa suma las partículas del núcleo.","difficulty":"media","timeLimit":60,"explanation":"Número de masa = protones + neutrones = 11 + 12 = 23."},{"id":"qui-07","question":"Se tienen dos compuestos: metano (CH₄) y agua (H₂O). En el metano, el carbono comparte electrones con el hidrógeno; en el agua, el oxígeno comparte electrones con el hidrógeno.\n¿Qué tipo de enlace presentan ambos compuestos?","options":["Iónico","Covalente","Metálico","Puente de hidrógeno"],"correct":1,"hint":"Compartir electrones es la marca de un tipo de enlace.","difficulty":"dificil","timeLimit":60,"explanation":"Cuando los átomos comparten electrones forman enlaces covalentes."},{"id":"qui-08","question":"La siguiente ecuación representa la reacción de formación de amoniaco (NH₃):\nN₂ + 3H₂ → 2NH₃\nSi se tienen 2 moles de N₂ y 6 moles de H₂, ¿cuántos moles de NH₃ se pueden producir como máximo?","options":["2 moles","4 moles","6 moles","8 moles"],"correct":1,"hint":"La ecuación dice que 1 mol de N₂ da 2 de NH₃. Revisa si el H₂ alcanza.","difficulty":"dificil","timeLimit":60,"explanation":"1 mol de N₂ reacciona con 3 de H₂ y da 2 de NH₃. Con 2 mol de N₂ y 6 de H₂ (proporción exacta) se forman 4 mol de NH₃."},{"id":"qui-09","question":"Un estudiante tiene tres líquidos: agua (densidad = 1.0 g/cm³), aceite (densidad = 0.9 g/cm³) y glicerina (densidad = 1.26 g/cm³). Los coloca en un mismo recipiente y observa que se forman tres capas.\n¿Cuál es el orden de las capas de abajo hacia arriba?","options":["Agua - Aceite – Glicerina","Glicerina - Agua – Aceite","Aceite - Agua – Glicerina","Glicerina - Aceite - Agua"],"correct":1,"hint":"Lo más denso se va al fondo.","difficulty":"dificil","timeLimit":60,"explanation":"Las capas se ordenan por densidad: glicerina (1,26) abajo, luego agua (1,0) y arriba aceite (0,9)."},{"id":"qui-10","question":"La siguiente tabla muestra los puntos de fusión y ebullición de cuatro sustancias:\nSustancia | Punto de fusión (°C) | Punto de ebullición (°C)\nBromo | -7 | 59\nHierro | 1538 | 2862\nCloro | -101 | -34\nOxígeno | -218 | -183\n¿Cuál de estas sustancias se encuentra en estado líquido a temperatura ambiente (25°C)?","options":["Bromo","Hierro","Cloro","Oxígeno"],"correct":0,"hint":"Compara cada temperatura con 25 °C: un líquido funde por debajo y hierve por encima.","difficulty":"facil","timeLimit":60,"explanation":"Una sustancia es líquida a 25 °C si funde por debajo de 25 °C y hierve por encima. El bromo funde a −7 °C y hierve a 59 °C: es líquido. El hierro sigue sólido (funde a 1538 °C), y el cloro y el oxígeno ya hirvieron (−34 °C y −183 °C): son gases."}]}$qui1$::jsonb,
      $qui2${"bank":"quimica","bankRound":2,"passingScore":0,"questions":[{"id":"qui-11","question":"El nitruro de silicio (Si₃N₄) se sintetiza mediante la siguiente reacción no balanceada a alta temperatura:\nSi(s) + N₂(g) → Si₃N₄(s)\nSi se hacen reaccionar 168 g de Silicio (Masa molar Si = 28 g/mol) con 140 g de nitrógeno gaseoso (Masa molar N₂ = 28 g/mol):\n(Masa molar del Si₃N₄ = 140 g/mol)\n¿Cuál es el reactivo límite y la masa máxima de Si₃N₄ que se puede producir?","options":["El reactivo límite es N₂ y se producen 280 g de Si₃N₄.","El reactivo límite es Si y se producen 280 g de Si₃N₄.","El reactivo límite es Si y se producen 140 g de Si₃N₄.","Ambos se consumen simultáneamente y se producen 308 g de Si₃N₄."],"correct":1,"hint":"Primero balancea: 3 Si + 2 N₂ → Si₃N₄. Luego calcula cuántas moles tienes de cada reactivo.","difficulty":"facil","timeLimit":90,"explanation":"3 Si + 2 N₂ -> Si₃N₄. 6 mol Si requiere 4 mol N₂. Si es el reactivo límite y da 2 mol = 280 g."},{"id":"qui-12","question":"Un recipiente rígido e indeformable de 10 L contiene un gas ideal a 27°C (300 K) y 2 atm de presión. Se transfiere calor al sistema hasta que la temperatura alcanza 327°C (600 K).\n¿Cuál será la nueva presión interna del recipiente y qué tipo de proceso termodinámico ocurrió?","options":["4 atm, proceso isocórico (isovolumétrico).","1 atm, proceso isobárico.","4 atm, proceso isotérmico.","2 atm, proceso adiabático."],"correct":0,"hint":"El recipiente es rígido: el volumen no cambia. Si la temperatura absoluta se duplica, ¿qué pasa con la presión?","difficulty":"media","timeLimit":90,"explanation":"Proceso isocórico (V constante): P2 = P1*(T2/T1) = 2*(600/300) = 4 atm."},{"id":"qui-13","question":"Considere el sistema en equilibrio gaseoso:\nN₂O₄(g) ⇌ 2 NO₂(g) ΔH = +57.2 kJ/mol\n(El N₂O₄ es incoloro y NO₂ café oscuro)\nSi la mezcla en equilibrio se somete a un aumento de temperatura y simultáneamente a una disminución de volumen (aumento de presión), ¿hacia dónde se desplazará el equilibrio respecto al color del sistema?","options":["El aumento de temperatura favorece la formación de NO₂ (más café), pero el aumento de presión favorece la formación de N₂O₄ (más claro); los efectos son opuestos.","Ambos cambios desplazan invariablemente el equilibrio hacia la derecha, tornando el sistema de color café muy intenso.","El sistema permanece inalterado porque los cambios de presión y temperatura se anulan numéricamente.","El equilibrio se desplaza únicamente hacia la izquierda tornando la mezcla completamente incolora."],"correct":0,"hint":"Le Châtelier: el calor favorece la reacción endotérmica y la presión favorece el lado con menos moles de gas.","difficulty":"dificil","timeLimit":90,"explanation":"Aumentar T favorece NO₂ y comprimir favorece N₂O₄; son efectos contrapuestos."},{"id":"qui-14","question":"Se titulan 50 mL de una solución de ácido fuerte HCl 0.1 M con una solución de base fuerte NaOH 0.1 M.\n¿Cuál es el pH de la solución cuando se han adicionado exactamente 25 mL de NaOH?","options":["pH = 1.48","pH = 7.00","pH = 12.52","pH = 2.00"],"correct":0,"hint":"Calcula los moles de HCl y de NaOH: ¿qué sobra y en cuánto volumen total queda?","difficulty":"dificil","timeLimit":90,"explanation":"Quedan 0.0025 mol HCl en 75 mL -> [H+] = 0.0333 M -> pH = 1.48."},{"id":"qui-15","question":"Para la reacción elemental 2A + B → C, la ecuación de velocidad experimental es:\nv = k [A]² [B]\nSi la concentración de A se duplica y la concentración de B se reduce a la mitad, ¿cómo cambia la velocidad de reacción inicial?","options":["Se mantiene constante.","Se duplica.","Se cuadruplica.","Se reduce a la cuarta parte."],"correct":1,"hint":"Reemplaza en la ecuación: [A] se duplica (¡y está al cuadrado!) y [B] se reduce a la mitad.","difficulty":"media","timeLimit":90,"explanation":"v' = k (2[A])^2 (0.5[B]) = 2 * k[A]²[B] = 2v."},{"id":"qui-16","question":"Teniendo en cuenta los siguientes potenciales estándar de reducción:\n- Cu²⁺ + 2e⁻ → Cu⁰ (E° = +0.34 V)\n- Zn²⁺ + 2e⁻ → Zn⁰ (E° = -0.76 V)\nSe construye una pila galvánica en condiciones estándar (25°C, 1 M). ¿Cuál es el potencial estándar de la celda (E°celda) y cuál es el ánodo?","options":["E°celda = +1.10 V; Ánodo: Electrodo de Zinc (Zn).","E°celda = +0.42 V; Ánodo: Electrodo de Cobre (Cu).","E°celda = -1.10 V; Ánodo: Electrodo de Zinc (Zn).","E°celda = +1.10 V; Ánodo: Electrodo de Cobre (Cu)."],"correct":0,"hint":"En la pila se oxida el metal con el potencial de reducción más bajo; E° = cátodo − ánodo.","difficulty":"media","timeLimit":90,"explanation":"E° = 0.34 - (-0.76) = +1.10 V. El Zn se oxida en el ánodo."},{"id":"qui-17","question":"Se disuelven 0.1 moles de (NaCl) en 1 kg de agua pura. En otro recipiente con 1 kg de agua pura se disuelven 0.1 moles de glucosa (C₆H₁₂O₆).\nSabiendo que el NaCl se disocia completamente (i = 2) y la glucosa es un no electrólito (i = 1):¿Cuál de las dos soluciones presentará un mayor punto de ebullición?","options":["La solución de glucosa, por tener un peso molecular mucho mayor.","La solución de NaCl, porque genera el doble de partículas efectivas de soluto en solución.","Ambas soluciones hervirán exactamente a la misma temperatura por tener la misma molalidad nominal.","La solución de NaCl, únicamente porque el cloro reacciona exotérmicamente con el agua."],"correct":1,"hint":"El punto de ebullición sube según el número de partículas disueltas, no según su masa.","difficulty":"dificil","timeLimit":90,"explanation":"NaCl disocia i=2, duplicando la cantidad de partículas efectivas en solución."},{"id":"qui-18","question":"Considere las siguientes dos fórmulas estructurales de compuestos orgánicos:\n1. CH₃–CH₂–CH₂–OH (1-propanol)\n2. CH₃–O–CH₂–CH₃ (metoxietano)\n¿Qué relación de isomería existe entre estas dos moléculas?","options":["Isómeros de cadena.","Isómeros de posición.","Isómeros de función (grupo funcional).","Estereoisómeros ópticos."],"correct":2,"hint":"Mismos átomos, pero una molécula es un alcohol (–OH) y la otra un éter (–O–).","difficulty":"media","timeLimit":90,"explanation":"Isómeros de función (alcohol vs éter)."},{"id":"qui-19","question":"Según la Teoría de Repulsión de Pares de Electrones de la Capa de Valencia (VSEPR), ¿cuál es la geometría molecular y el ángulo de enlace aproximado de la molécula de agua (H₂O)?","options":["Lineal, 180°.","Trigonal Plana, 120°.","Angular, ≈104.5° (debido a la repulsión de los 2 pares de electrones libres sobre el oxígeno).","Tetraédrica perfecta, 109.5°."],"correct":2,"hint":"El oxígeno tiene 2 pares de electrones libres que empujan los enlaces.","difficulty":"media","timeLimit":90,"explanation":"Geometría angular reducida a ~104.5° por repulsión de pares libres."},{"id":"qui-20","question":"Dadas las reacciones:\n1. C(s) + O₂(g) → CO₂(g) ΔH₁ = -393.5 kJ\n2. CO(g) + 1/2 O₂(g) → CO₂(g) ΔH₂ = -283.0 kJ\nAplicando la Ley de Hess, ¿cuál es el cambio de entalpía (ΔH) para la reacción de combustión incompleta del carbono: C(s)+1/2O₂(g)→CO(g)?","options":["-110.5 kJ","-676.5 kJ","+110.5 kJ","+676.5 kJ"],"correct":0,"hint":"Invierte la segunda reacción y súmala con la primera.","difficulty":"dificil","timeLimit":90,"explanation":"Ley de Hess: -393.5 + 283.0 = -110.5 kJ."}]}$qui2$::jsonb)
    ) as t(area, label, base_id, r1, r2)
  loop
    if f.base_id is null then
      insert into _0075_estado values (1, f.label, 'CURSO NO ENCONTRADO', 'No existe en esta base de datos: no se cambió nada.');
      continue;
    end if;

    for c in
      select id, name, draft_modules is not null as has_draft from public.courses
       where id = f.base_id or parent_course_id = f.base_id
       order by parent_course_id nulls first, name
    loop
      -- Un borrador sin publicar en el editor de ruta trae los módulos 4 y 6
      -- VIEJOS: si el tutor lo publica, deshace esta migración en su colegio.
      if c.has_draft then
        insert into _0075_estado values (3, f.label, 'BORRADOR PENDIENTE',
          c.name || ': tiene un borrador sin publicar en el editor de ruta. Que el tutor lo descarte (o importe la ruta base) antes de publicar, o volverán los módulos 4 y 6 anteriores.');
      end if;
      foreach v_ronda in array array[4, 6] loop
        v_cd := case when v_ronda = 4 then f.r1 else f.r2 end;
        v_mod_ronda := case when v_ronda = 4 then 'primera ronda' else 'ronda final' end;
        select * into m from public.course_modules where course_id = c.id and "order" = v_ronda;

        if m.id is null then
          insert into _0075_estado values (2, f.label, 'SIN MÓDULO ' || v_ronda, c.name || ': la ruta no tiene módulo en la posición ' || v_ronda || '.');
        elsif m.type = 'challenge' and m.challenge_data ? 'bank' then
          insert into _0075_estado values (2, f.label, 'YA APLICADA', c.name || ' · ' || m.title || ' (' || v_mod_ronda || ')');
        elsif m.type = 'lesson'
          and (m.content @> '[{"title":"Pendiente"}]'::jsonb or m.content::text like '%Banco de preguntas%') then
          update public.course_modules
             set type = 'challenge',
                 challenge_type = 'quiz',
                 challenge_data = v_cd,
                 -- Se conserva la guía del bloque (frase de apertura, cómo
                 -- ejecutarlo); se retira el marcador "Pendiente" y el banco
                 -- viejo en texto, que ahora vive como preguntas reales.
                 content = coalesce((
                   select jsonb_agg(e order by i)
                     from jsonb_array_elements(m.content) with ordinality as t(e, i)
                    where coalesce(e->>'title', '') <> 'Pendiente'
                      and coalesce(e->>'title', '') not like 'Banco de preguntas%'
                 ), '[]'::jsonb),
                 updated_at = now()
           where id = m.id;
          insert into _0075_estado values (2, f.label, 'APLICADA',
            format('%s · %s (%s): %s preguntas.', c.name, m.title, v_mod_ronda, jsonb_array_length(v_cd->'questions')));
        else
          insert into _0075_estado values (2, f.label, 'NO TOCADO',
            format('%s · %s (%s): ya tiene contenido propio (%s). Cárgale preguntas desde el editor de ruta.', c.name, m.title, v_mod_ronda, m.type));
        end if;
      end loop;
    end loop;
  end loop;
end $$;

select asignatura, estado, detalle from _0075_estado order by paso, asignatura, estado, detalle;
